INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(9635, 'plPL', 'Ekstraktor drobin Zapthrottle\'a!', 'Bagienny gaz to niesamowita rzecz i bardzo się przydaje, mon! Ale najpierw trzeba go umieć wessać, a do tego, przyjacielu, potrzebny jest ekstraktor drobin Zapthrottle\'a.$B$BMógłbym ci po prostu dać schematy, ale najpierw chcę czegoś w zamian. Może jakichś części zamiennych? Kiedy ostatnio sprawdzałem, sporo ich leżało przy zepsutej pompie parowej na Martwym Grzęzawisku, daleko na północnym wschodzie.$B$BSłyszałem, że uschnięte olbrzymy rozwlekły te części po całym wyschniętym dnie jeziora.', 'Przynieś 15 części pompy parowej Mackowi Diverowi w Zabra\'jin na Moczarach Zangarskich.', '', 'Wróć do Macka Divera w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9636, 'plPL', 'Ekstraktor drobin Zapthrottle\'a!', '$GWidziałeś:Widziałaś; ten bagienny gaz? Czyż nie jest błyszczący?$B$BŻeby go wyssać do sucha, potrzeba ekstraktora drobin Zapthrottle\'a. Mogłabym ci dać plany, jak go zrobić, ale naprawdę potrzebuję części zamiennych, żeby tu wszystko ponaprawiać.$B$BKiedy ostatnio sprawdzałam, sporo części leżało przy pompie parowej na Martwym Grzęzawisku na północnym wschodzie. Chyba to uschnięte olbrzymy zepsuły tamtą pompę.$B$BTo co, pomożemy sobie nawzajem?', 'Przynieś 15 części pompy parowej K. Lee Smallfry w Telredorze na Moczarach Zangarskich.', '', 'Wróć do K. Lee Smallfry w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9697, 'plPL', 'Wartowniczka Leesa\'oh', 'Trzeba przeprowadzić ważne badania nad ekologią tutejszych stworzeń, zwłaszcza zarodniaków i władców trzęsawisk. I uwierz mi, kiedy już ruszysz w teren, przekonasz się, że to wymagająca praca.$B$BOdszukaj Wartowniczkę Leesa\'oh w Strażnicy Cenariona, w zachodniej części moczarów, bliżej południa. Idź ścieżką na zachód, a w końcu ją znajdziesz. Bywa trochę... zbyt naukowa, ale nie przejmuj się tym.$B$BA, i uważaj na jej kota.', 'Porozmawiaj z Wartowniczką Leesa\'oh w Strażnicy Cenariona na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9701, 'plPL', 'Obserwacja zarodniaków', 'Musimy się dowiedzieć jak najwięcej o zarodniakach ze Sporeggaru i ich relacjach z okolicznymi stworzeniami. Jednym ze sposobów jest to, co robię ja: bierna obserwacja i notowanie ich wzajemnych zachowań.$B$BIdź do Jaru Wylęgu na zachodzie. Zbadaj całą okolicę, a potem wróć i opowiedz mi, co $gwidziałeś:widziałaś;.', 'Zbadaj Jar Wylęgu na Moczarach Zangarskich, a potem przekaż swoje spostrzeżenia Wartowniczce Leesa\'oh w Strażnicy Cenariona na Moczarach Zangarskich.', 'Zbadaj Jar Wylęgu', 'Wróć do Wartowniczki Leesa\'oh w Strażnicy Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9702, 'plPL', 'Kwestia obżarstwa', 'Zastanawiałam się, czemu władcy trzęsawisk przechodzą przez drogę do Jaru Wylęgu – z jakiegoś powodu muszą głodować. Tak być nie może!$B$BNormalnie bym się w to nie mieszała, ale jeśli dalej będą zjadać wszystkie strąki zarodniaków, to je wytępią!$B$BZrobimy tak: ja zostanę tutaj, a ty idź na Grań Quagg na wschodzie i poszukaj w ich diecie wskazówek, dlaczego napadają na zarodniaki.', 'Zbierz 10 porcji wyrzuconej pożywki, a potem wróć do Wartowniczki Leesa\'oh w Strażnicy Cenariona na Moczarach Zangarskich.', '', 'Wróć do Wartowniczki Leesa\'oh w Strażnicy Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9708, 'plPL', 'Znajome grzyby', 'Tak, właśnie! Wiedziałam, że widziałam już ten typ grzybów gdzie indziej na moczarach!$B$BNa północy leży miejsce zwane Wyrąbanym Trzęsawiskiem. Dziwna nazwa, jak dla mnie, ale nigdy tam nie byłam. Potrzebuję próbek tamtejszych grzybów, żeby potwierdzić moją hipotezę.$B$BTylko uważaj, $N. Słyszałam, że w okolicy osiedliły się ogry, więc będziesz $gmusiał:musiała; odebrać próbki właśnie im. Może dlatego władcy trzęsawisk nie chodzą już tam po jedzenie?', 'Zbierz 15 próbek grzybów i zanieś je Wartowniczce Leesa\'oh w Strażnicy Cenariona na Moczarach Zangarskich.', '', 'Wróć do Wartowniczki Leesa\'oh w Strażnicy Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9709, 'plPL', 'Odzyskanie grzybów', '$N, mam pomysł. Chcę, żebyś znów $gposzedł:poszła; na północ, tym razem w samo serce ziem ogrów!$B$BNa północny zachód od Wyrąbanego Trzęsawiska jest miejsce zwane Warownią Ango\'rosh. Leży na pływającej wyspie, do której prowadzi wielki grzybowy most.$B$BOgry muszą tam składować zebrane grzyby. Założę się, że znajdziesz je wszędzie, pewnie także przy samych ograch!$B$BPrzynieś mi ich dość, a spróbuję zapewnić władcom trzęsawisk nowe źródło pożywienia.', 'Zbierz 10 skrzynek grzybów i zanieś je Wartowniczce Leesa\'oh w Strażnicy Cenariona na Moczarach Zangarskich.', '', 'Wróć do Wartowniczki Leesa\'oh w Strażnicy Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9714, 'plPL', 'Przynieś mi jeszcze jeden krzaczek!', '', '', '', 'Wróć do Gzhun\'tta w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9715, 'plPL', 'Przynieś mi krzaczek!', 'Musimy uzupełnić zapasy krwistego hibiskusa, którego używamy do wielu celów. Kiedyś rósł gęsto jak krzaki, ale przez spadek poziomu wody na moczarach można go teraz znaleźć już tylko w Podbagnie w Zbiorniku Żmijokolców, pod Wężowym Jeziorem.$B$BPodobno tamtejsze łazęgi, trzęsawiskowe olbrzymy i podbagienne nietoperze uważają go za przysmak. Jeśli więc chcesz nam pomóc, musisz odebrać im te kwiaty.', 'Zbierz 5 krwistych hibiskusów i zanieś je Gzhun\'ttowi w Sporeggarze na Moczarach Zangarskich.', '', 'Wróć do Gzhun\'tta w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9716, 'plPL', 'Niepokój nad Jeziorem Cienistych Mokradeł', 'Przybyliśmy do Rubieży w przekonaniu, że znajdziemy tu tylko nieliczne skrawki życia. Na Moczarach Zangarskich odkryliśmy bujne środowisko i kwitnący ekosystem.$B$BNasza pierwsza ocena okolicy okazała się jednak zwodnicza. Odkąd zaczęliśmy prowadzić pomiary, poziom wody w jeziorach i na moczarach stale spada.$B$BSkutki dla tutejszej fauny i flory mogą być katastrofalne. Idź nad Jezioro Cienistych Mokradeł, na południowy zachód stąd, i poszukaj wskazówek, skąd bierze się ten ubytek wody.', 'Zbadaj przyczynę ubytku wody w Jeziorze Cienistych Mokradeł. Potem wróć do Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', 'Jezioro Cienistych Mokradeł zbadane', 'Wróć do Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9717, 'plPL', 'No to się zaczęło!', 'Choć jesteśmy pokojowym ludem, chcąc nie chcąc toczymy wojnę z zarodnikowymi olbrzymami. A mamy takie powiedzenie, że w grzybach i na wojnie wszystkie chwyty dozwolone!$B$BJeden z przywódców zarodnikowych olbrzymów, Hungarfen, od tysiącleci pielęgnuje do perfekcji wyjątkową roślinę zwaną podzarodnikiem. Złamałoby go, gdyby tej roślinie coś się stało.$B$BUdaj się do Podbagna w Zbiorniku Żmijokolców i ukradnij dla nas jeden jej liść. Uwierz mi, on to zauważy.', 'Zdobądź liść podzarodnika i zanieś go T\'shu w Sporeggarze na Moczarach Zangarskich.', '', 'Wróć do T\'shu w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9718, 'plPL', 'W linii prostej', 'Musimy ustalić, jak szeroko zakrojone są działania nag, i odpowiednio na nie zareagować.$B$BZbadanie każdego zbiornika wodnego na Moczarach Zangarskich mogłoby zająć sporo czasu. Jeśli mi pozwolisz, użyję magii, by nadać ci kształt lepiej nadający się do zwiadu nad moczarami.$B$BGdy będziesz $ggotów:gotowa;, unieś ten amulet nad balkonem obok mnie. Kiedy skończymy, sprowadzę cię z powrotem w bezpieczne miejsce.', 'Ysiel Pieśń Wiatru chce, żebyś $gużył:użyła; Amuletu Burzowej Wrony do zbadania głównych jezior Moczarów Zangarskich.', 'Jeziora Moczarów Zangarskich zbadane', 'Wróć do Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9719, 'plPL', 'Tropienie Tropiciela', 'Od zawsze największym zagrożeniem dla mojego ludu były bagienne wędrowce. Wobec nowych kłopotów z zarodnikowymi olbrzymami nie możemy sobie pozwolić na kolejny atak naszych odwiecznych wrogów.$B$B$GUdowodniłeś:Udowodniłaś;, że wiele potrafisz, $N. Czy dasz radę wyprawić się do Podbagna w Zbiorniku Żmijokolców i zabić wielką matkę bagiennych wędrowców, zwaną Czarnym Tropicielem?!$B$BPrzynieś mi jej mózg jako dowód.', 'Przynieś Mózg Czarnego Prześladowcy Khn\'nixowi w Sporeggarze na Moczarach Zangarskich.', '', 'Wróć do Khn\'nixa w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9720, 'plPL', 'Trzeba zachować równowagę', 'Nie potrafię pojąć, dlaczego nagi miałyby wypompowywać wodę z własnego środowiska. Rozumiem za to, że trzeba położyć kres ich działaniom.$B$BTe nasiona niosą w sobie gniew ziemi. Zanieś je do pomp parowych obsługiwanych przez nagi i użyj ich na sterowaniu.$B$BPnącza, które wyrosną z nasion, będą grube jak twoje ramię i mocne jak żelazo. Idź, $N. Przywróć równowagę, którą zaburzyły nagi.', 'Ysiel Pieśń Wiatru chce, żebyś $gużył:użyła; nasion żelaznego pnącza na sterowaniu pomp parowych przy Wężowym Jeziorze, Jeziorze Cienistych Mokradeł, Jeziorze Błędnych Ogników i Lagunie. Potem wróć do niej do Schronienia Cenariona na Moczarach Zangarskich z pozostałymi nasionami.', '', 'Wróć do Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', 'Sterowanie przy Jeziorze Cienistych Mokradeł unieruchomione', 'Sterowanie przy Jeziorze Błędnych Ogników unieruchomione', 'Sterowanie przy Wężowym Jeziorze unieruchomione', 'Sterowanie w Lagunie unieruchomione', 0),
(9726, 'plPL', 'Skoro już jesteśmy przyjaciółmi...', 'Nagi z Enklawy Krwawej Łuski na północnym wschodzie zaczęły zabijać nasz lud. Nie możemy na to pozwolić, $N!$B$BProponujemy, żebyś $gdał:dała; im nauczkę na dowód naszej przyjaźni.', 'Zabij 12 poganiaczy niewolników Krwawej Łuski i 6 zaklinaczek Krwawej Łuski, a potem wróć do Gzhun\'tta w Sporeggarze na Moczarach Zangarskich.', '', 'Wróć do Gzhun\'tta w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9727, 'plPL', 'Skoro wciąż jesteśmy przyjaciółmi...', 'Dochodzą nas wieści, że nagi z Enklawy Krwawej Łuski na północnym wschodzie nadal zabijają nasz lud. Myśleliśmy, że już się tym $gzająłeś:zajęłaś;, $N!$B$BProponuję, żebyś $gdał:dała; im nauczkę na dowód naszej nieustającej przyjaźni.', 'Zabij 12 poganiaczy niewolników Krwawej Łuski i 6 zaklinaczek Krwawej Łuski, a potem wróć do Gzhun\'tta w Sporeggarze na Moczarach Zangarskich.', '', 'Wróć do Gzhun\'tta w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9728, 'plPL', 'Ciepłe powitanie', 'Druidzi z ekspedycji zajmują się badaniem roślin i jezior, a ja wziąłem na siebie rozprawianie się z wrogami w okolicy.$B$BOd kiedy postawiliśmy stopę na Moczarach Zangarskich, nagi bez ostrzeżenia przypuszczają na nas zabójcze ataki. Robimy, co w naszej mocy, by trzymać je na dystans, ale nasze zasoby są ograniczone.$B$BChcę, żebyś $gruszył:ruszyła; do różnych twierdz nag na Moczarach Zangarskich i $gpokazał:pokazała; im, że z nami się nie zadziera. Przynieś mi ich szpony jako dowód zwycięstw.', 'Strażnik Hamoot w Schronieniu Cenariona chce, żebyś $gprzyniósł:przyniosła; mu 30 szponów nag.', '', 'Wróć do Strażnika Hamoota w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9729, 'plPL', 'Fhwoor miażdżyć!', 'Małe nagi złościć Fhwoor! Zarodniaki dobre przyjaciele Fhwoor, więc Fhwoor zabrać arka nag.$B$BMy iść do pobliska wioska nag. Ty pomóc? Brać przyjaciele!', 'Eskortuj Fhwoora w okolice pompy parowej nad Jeziorem Błędnych Ogników, by odzyskać Arkę Ssslitha. Sprowadź Fhwoora i arkę bezpiecznie z powrotem, a potem zamelduj się u Gzhun\'tta w Sporeggarze na Moczarach Zangarskich.', 'Arka Ssslitha bezpiecznie dostarczona do Sporeggaru', 'Wróć do Gzhun\'tta w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9730, 'plPL', 'Przywódca Mrocznego Grzebienia', 'Ekspedycja Cenariońska niniejszym wyznacza nagrodę za Radżę Haghazeda, przywódcę nag z Mrocznego Grzebienia. Zwiadowcy cenariońscy ostatnio widzieli Haghazeda w Lagunie, w środkowo-południowej części Moczarów Zangarskich.$B$BMroczny Grzebień ma na sumieniu liczne ataki na Ekspedycję Cenariońską, a jego przywódcę uważa się za niezwykle niebezpiecznego.$B$BChętni do odebrania nagrody powinni zgłosić się do Strażnika Hamoota.', 'Zabij Radżę Haghazeda w Lagunie i wróć po nagrodę do Strażnika Hamoota z Ekspedycji Cenariońskiej na Moczarach Zangarskich.', '', 'Wróć do Strażnika Hamoota w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9731, 'plPL', 'Schematy odpływów', 'Zdobyte schematy przedstawiają podziemny system odpływów i pomp, który łączy jeziora w okolicy z Wężowym Jeziorem.$B$BJeśli schematy są prawdziwe, na środku Wężowego Jeziora znajduje się olbrzymi odpływ. Sprawdź to i zanieś wieści do Schronienia Cenariona.', 'Przeszukaj Wężowe Jezioro w poszukiwaniu śladów odpływu. Wróć do Ysiel Pieśni Wiatru w Schronieniu Cenariona z wieściami o swoim odkryciu.', 'Odpływ odnaleziony', 'Wróć do Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9738, 'plPL', 'Zaginieni w akcji', 'Musisz mi pomóc! Ysiel przysłała nas tutaj, żebyśmy zbadali zagadkę pomp parowych i tego, po co używa się ich do osuszania moczarów. Ale moi przyjaciele rozdzielili się i lekkomyślnie poszli dalej beze mnie.$B$BCzasem ta czwórka potrafi być okropna, ale i tak ich kocham.$B$BDlatego potrzebuję, żebyś $godkrył:odkryła;, co się z nimi stało, choć obawiam się najgorszego. Szukaj ich zarówno w Zagrodach Niewolników, jak i w Podbagnie.$B$BDziękuję ci, $N.', 'Dowiedz się, co się stało z Wiążącym ziemię Rayge\'em, Przyrodnikiem Ugryzienie, Plewiarzem Zielonorękim i Przywoływaczem wiatru Pazurem. Potem wróć do Wartowniczki Jhang w Zbiorniku Żmijokolców na Moczarach Zangarskich.', '', 'Wróć do Wartowniczki Jhang nad Wężowym Jeziorem na Moczarach Zangarskich.', 'Wiążący ziemię Rayge odnaleziony', 'Przyrodnik Ugryzienie odnaleziony', 'Plewiarz Zielonoręki odnaleziony', 'Przywoływacz wiatru Pazur odnaleziony', 0),
(9739, 'plPL', 'Niedola zarodniaków', 'Hej, ty! Musisz nam pomóc!$B$BGrzybowe olbrzymy pożerają wszystkie nasze worki zarodników! Musisz coś zrobić, bo stracimy nasze młode!$B$BWorki zarodników na początku są duże i kurczą się w miarę, jak ubywa w nich powietrza. Szukaj małych, dojrzałych worków zarodników i ocal ich tyle, ile zdołasz!', 'Fahssn w Jarze Wylęgu chce, żebyś $gzebrał:zebrała; 10 dojrzałych worków zarodników.', '', 'Wróć do Fahssna w Jarze Wylęgu na Moczarach Zangarskich.', '', '', '', '', 0),
(9742, 'plPL', 'Więcej worków zarodników', '', '', '', 'Wróć do Fahssna w Jarze Wylęgu na Moczarach Zangarskich.', '', '', '', '', 0),
(9743, 'plPL', 'Naturalni wrogowie', 'My, zarodniaki, nigdy nie żyliśmy dobrze z władcami trzęsawisk. Dawniej udawało się nam trzymać ich na dystans włóczniami i kamieniami. Ostatnio jednak zrobili się chyba bardziej agresywni... albo bardziej zdesperowani. Nie boją się ani nas, ani naszej broni.$B$BTy jesteś o wiele $ggroźniejszy:groźniejsza; i lepiej $guzbrojony:uzbrojona; niż my. Gdybyś $gzechciał:zechciała; walczyć za nas z władcami trzęsawisk, bylibyśmy twoimi dłużnikami na zawsze! Przynieś mi ich wici, żebym wiedział, ilu ich $gzabiłeś:zabiłaś;.', 'Fahssn w Jarze Wylęgu na Moczarach Zangarskich chce, żebyś $gprzyniósł:przyniosła; mu 6 wici władców trzęsawisk.', '', 'Wróć do Fahssna w Jarze Wylęgu na Moczarach Zangarskich.', '', '', '', '', 0),
(9744, 'plPL', 'Więcej wici!', '', '', '', 'Wróć do Fahssna w Jarze Wylęgu na Moczarach Zangarskich.', '', '', '', '', 0),
(9747, 'plPL', 'Plemię Cienistych Mokradeł', 'Nagi są straszne, tak. Ale jeszcze straszniejsze są zdradzieckie plemiona Złamanych i Zagubionych, które im pomogły!$B$BNajgorsi ze wszystkich są Zagubieni z plemienia Cienistych Mokradeł; używają mrocznej magii, by chwytać i zniewalać innych. Są szczególnie okrutni dla zbiegłych niewolników i poderżnęliby mi gardło, gdybym choć na dzień opuścił schronienie.$B$BUdaj się do Wioski Cienistych Mokradeł na południe stąd i zabij ich oraz ich przywódcę, Kataru. Do tego czasu każdego dnia będę się bał o swoje życie.', 'Ikeyen w Schronieniu Cenariona chce, żebyś $gudał:udała; się do Wioski Cienistych Mokradeł i $gzabił:zabiła; Kataru, 8 jasnowidzów z Cienistych Mokradeł, 6 znachorów z Cienistych Mokradeł i 6 wyroczni z Cienistych Mokradeł.', '', 'Wróć do Ikeyena w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9752, 'plPL', 'Ucieczka z Cienistych Mokradeł', 'Musisz mi pomóc się stąd wydostać!$B$BZbierałam zioła niedaleko, kiedy garstka tych małych dzikusów mnie porwała. Próbowałam się bronić, ale było ich za dużo.$B$BPomóż mi wrócić do Schronienia Cenariona, z dala od tych okrutnych nędzników i ich plugawej magii!', 'Eskortuj Kayrę Długogrzywą do Schronienia Cenariona na Moczarach Zangarskich. Po wykonaniu zadania zamelduj się u Ysiel Pieśni Wiatru.', 'Odprowadź Kayrę Długogrzywą w bezpieczne miejsce', 'Wróć do Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9763, 'plPL', 'Kryjówka wodza', 'Czasem opłaca się ukryć bardzo, bardzo cicho przy wejściu do kryjówki wroga.$B$BZaledwie kilka godzin temu widziałam, jak grupa nag przechodzi przez kamienny łuk do drugiego tunelu od lewej. Nie znam dobrze ich języka, ale jedno słowo zrozumiałam wyraźnie: Kalithresh.$B$BTo musi być wejście do Krypty Pary, skąd Wódz Kalithresh dowodzi swoimi oddziałami. Musisz go znaleźć i powstrzymać. Jestem zbyt słaba, żeby ci w czymkolwiek pomóc.', 'Wartowniczka Jhang chce, żebyś $godnalazł:odnalazła; i $gzabił:zabiła; Wodza Kalithresha w Zbiorniku Żmijokolców.', '', 'Wróć do Wartowniczki Jhang nad Wężowym Jeziorem na Moczarach Zangarskich.', '', '', '', '', 0),
(9764, 'plPL', 'Rozkazy od Lady Vash', 'Ten list zawiera szczegółowe rozkazy dla nag ze Żmijokolców, które obsługują Kryptę Pary. Ostrzega przed przybyciem w te strony druidów cenariońskich i nakazuje zabijać ich na miejscu. Tempo przekierowywania wody z innych jezior do Zbiornika Żmijokolców ma zostać podwojone. Rozkazy noszą pieczęć osławionej Lady Vash.$B$BTen list bardzo zainteresowałby druidów z Ekspedycji Cenariońskiej. Zanieś go ich przywódczyni, Ysiel Pieśni Wiatru.', 'Dostarcz Rozkazy od Lady Vash Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9765, 'plPL', 'Przygotowania do wojny', 'Ekspedycja Cenariońska zaczynała jako pokojowe przedsięwzięcie, a teraz stoimy w obliczu otwartej wojny z nagami.$B$BMamy wielu chętnych do walki, ale kiepsko uzbrojonych. Przynieś mi broń samych nag, byśmy mogli przekuć ją na glewie i groty strzał.$B$BTylko najlepsze uzbrojenie da nam przydatne materiały, $N. Będziesz $gmusiał:musiała; poszukać nag w Zbiorniku Żmijokolców.', 'Zdobądź uzbrojenie Żmijokolców od nag w Zbiorniku Żmijokolców i zanieś je Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', '', 'Wróć do Ysiel Pieśni Wiatru w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9766, 'plPL', 'Uzbrojenie Żmijokolców', '', '', '', 'Wróć do Ysiel Pieśni Wiatru.', '', '', '', '', 0),
(9769, 'plPL', 'O gustach się nie dyskutuje', '<Magasha chichocze cicho pod nosem.>$B$BZałożę się, że gdyby wiedzieli, że noszą kawałki robali, ta moda skończyłaby się bardzo szybko.$B$BNajpierw zaczęliśmy zabijać tutejsze robale, bo przeszkadzały nam w budowie. Aż tu jakiś przedsiębiorczy kupiec zatrzymuje się tu na noc i ani się obejrzysz, a on skupuje wszystkie robacze skrzydła, jakie mamy!$B$BMówi, że szyje z nich ubrania. Ja tam zostaję przy swojej zbroi, dzięki. Ale jak nazbierasz skrzydeł świetlików, chętnie je od ciebie kupię.', 'Przynieś 8 przejrzystych skrzydeł dowolnego gatunku świetlików z Moczarów Zangarskich Magashy na Posterunku Bagiennego Szczura.', '', 'Wróć do Magashy na Posterunku Bagiennego Szczura na Moczarach Zangarskich.', '', '', '', '', 0),
(9770, 'plPL', 'Groźne bagiennokły', 'Czasem żałuję, że Denjai nie wysłał z nami szamana albo chociaż nie dał nam totemu, który trzymałby bagiennokłe rozpruwacze na dystans.$B$BCała okolica aż się roi od tych szkodników! To nienormalne. Czy coś nie powinno zjadać tych obrzydliwych stworów?$B$BWszyscy na zmianę bawimy się w tępicieli. $GZjawiłeś:Zjawiłaś; się w samą porę, $N. Gratulacje! A teraz ruszaj i wyczyść okolicę z bagiennokłów!', 'Reavij na Posterunku Bagiennego Szczura chce, żebyś $gzabił:zabiła; 10 bagiennokłych rozpruwaczy.', '', 'Wróć do Reavija na Posterunku Bagiennego Szczura na Moczarach Zangarskich.', '', '', '', '', 0),
(9771, 'plPL', 'Poszukiwania zwiadowcy Jyoby', 'Teraz, gdy znasz już teren, chciałbym cię prosić o pomoc w czymś innym. Okolica na północnym zachodzie, którą zaczęliśmy nazywać Martwym Grzęzawiskiem, to upiorne miejsce. Nikt nie widział tam niczego żywego, ale też nikt nie został tam długo.$B$BZwiadowca Jyoba zgłosił się na ochotnika, żeby zbadać okolicę i zdać raport. Opuścił posterunek trzy dni temu i nie wrócił. To do niego niepodobne, żeby znikać na tak długo bez żadnej wiadomości. Poszukasz go, $N?', 'Poszukaj zwiadowcy Jyoby na Martwym Grzęzawisku na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9772, 'plPL', 'Raport Jyoby', 'Ciało zwiadowcy Jyoby jest upstrzone drobinami uschniętego grzyba. Cokolwiek go zabiło, musiało składać się z tego samego obumierającego grzyba co olbrzymie więdnące grzyby Martwego Grzęzawiska. Być może któryś z uschniętych olbrzymów zaskoczył go, gdy siedział i pisał raport.$B$BBez treści raportu nie sposób się dowiedzieć, co odkrył zwiadowca. Jeśli uda się go odnaleźć, należy oddać go Zuraiowi.', 'Odbierz Raport zwiadowcy Jyoby uschniętym olbrzymom i zanieś go Zuraiowi na Posterunku Bagiennego Szczura.', '', 'Wróć do Zuraia na Posterunku Bagiennego Szczura na Moczarach Zangarskich.', '', '', '', '', 0),
(9773, 'plPL', 'Dość grzybów!', 'Zupa grzybowa, gulasz grzybowy, sos grzybowy!$B$BGrzyby, grzyby, grzyby! Nic innego tu do jedzenia nie ma. Jak powiesz, że jesteś $ggłodny:głodna;, kucharz daje ci topór i każe iść ściąć sobie obiad!$B$BA ja mam dość grzybów. Widziałam ryby w tutejszych jeziorach. Pewnie, wyglądają paskudnie, ale muszą być lepsze niż grzyby!$B$BIle mnie będzie kosztować wynajęcie cię, żebyś $gprzyniósł:przyniosła; mi pierwszy porządny posiłek od tygodni?', 'Zdobądź 8 filetów z węgorza z węgorzy z Cienistych Mokradeł i zanieś je Magashy na Posterunku Bagiennego Szczura.', '', 'Wróć do Magashy na Posterunku Bagiennego Szczura na Moczarach Zangarskich.', '', '', '', '', 0),
(9774, 'plPL', 'Grube łuski hydry', 'Reavij mądrze zrobił, że wziął skórzaną zbroję. To bagno wkrótce zupełnie zniszczy moją kolczugę.$B$BW miarę możliwości wymieniam łuski kawałek po kawałku. Hydry na moczarach mają grube, ochronne łuski, które dobrze znoszą wilgoć ich siedlisk.$B$BZnalezienie odpowiednich to jednak żmudne zajęcie. Zbyt często najlepsze łuski są rozdarte albo zbyt cienkie, by nadawały się na zbroję. Przynoś mi każdą dobrą, jaką zdobędziesz od hydr z większych jezior.', 'Zurai na Posterunku Bagiennego Szczura chce, żebyś $gprzyniósł:przyniosła; mu 12 grubych łusek hydry.', '', 'Wróć do Zuraia na Posterunku Bagiennego Szczura na Moczarach Zangarskich.', '', '', '', '', 0),
(9775, 'plPL', 'Meldunek u łowcy cieni Denjaia', 'Łowca cieni Denjai na pewno spodziewa się raportu o postępach w zakładaniu naszej placówki. Przygotowałem krótkie podsumowanie tego, co już tu osiągnęliśmy, ale po stracie zwiadowcy Jyoby nie mogę oddelegować gońca, żeby zaniósł raport do bazy Denjaia w Zabra\'jin na zachodzie.$B$BJeśli zmierzasz w tamtą stronę, może zaniesiesz mu to? Łowca cieni Denjai na początku potrafi trochę onieśmielać, ale kiedy się do niego przywyknie, nie jest taki zły.', 'Zanieś Raport Zuraia łowcy cieni Denjaiowi w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9776, 'plPL', 'Przystań Orebor', 'Jak wiesz, wielu mieszkańców Telredoru to uchodźcy z wojny, która zdziesiątkowała draenei. Moim celem jest utrzymanie Telredoru jako bezpiecznej przystani dla wszystkich naszych sojuszników w tej walce. Są tacy, którzy pragną się do nas przyłączyć, ale czują, że nie są jeszcze gotowi.$B$BJesteśmy im winni wszelką pomoc, jakiej możemy udzielić, $N. Grupa Złamanych pod wodzą Ikutiego schroniła się w ruinach starej świątyni na północny zachód od Wężowego Jeziora. Odszukaj ich i wyciągnij do nich rękę w geście przyjaźni.', 'Porozmawiaj z Ikutim w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9777, 'plPL', 'Zarodniki blaskowca', 'Na tym bagnie niewiele się pali, więc musimy oświetlać Telredor innymi sposobami. Wiele stworzeń i roślin na moczarach wydziela łagodną poświatę.$B$BZamykanie świecących stworzeń jest trudne i okrutne, więc źródłem światła zrobiliśmy pewien gatunek grzyba.$B$BZbieramy i hodujemy tu grzyb zwany blaskowcem, ale nasze potrzeby zmuszają nas, by co jakiś czas zbierać nowe plony. Te małe zielone grzyby często rosną u podstawy większych w pobliżu Telredoru.', 'Przynieś 6 zarodników blaskowca Ruamowi w Telredorze.', '', 'Wróć do Ruama w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9778, 'plPL', 'Strażnik Hamoot', 'Zanim opuścisz Schronienie Cenariona, koniecznie porozmawiaj ze Strażnikiem Hamootem. Odpowiada za bezpieczeństwo ekspedycji.$B$BNigdy by mi nie wybaczył, gdybym nie wysłała do niego $gtakiego doświadczonego poszukiwacza przygód:takiej doświadczonej poszukiwaczki przygód; jak ty.', 'Zamelduj się u Strażnika Hamoota w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9780, 'plPL', 'Filety z węgorzy z Cienistych Mokradeł', 'Dobrze widzieć tu kolejną nową twarz. Kiedy Haalrun i ja przybyliśmy do Telredoru, byliśmy jedynymi przybyszami z zewnątrz, ale to było jakby w innym życiu.$B$BMimo to staramy się witać nowo przybyłych i dbać o to, by zawsze było dość jedzenia i zapasów. Nigdy w pełni nie odwdzięczymy się anachoretom z Telredoru za ich dobroć, ale możemy iść za ich przykładem i okazywać ją innym.$B$BJeśli chcesz pomóc, w pobliskich jeziorach żyje ryba zwana węgorzem z Cienistych Mokradeł, której mięso to podstawa naszej diety.', 'Noraani w Telredorze chce, żebyś $gprzyniósł:przyniosła; jej 8 filetów z węgorza.', '', 'Wróć do Noraani w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9781, 'plPL', 'Za dużo gąb do wykarmienia', 'Podczas ostatniego polowania zauważyłem nową placówkę, którą buduje grupa trolli. Bez wątpienia oni też zaczęli polować na tych ziemiach.$B$BJeśli osiądą tu na stałe, walka o pożywienie będzie zacięta. Nie możemy wystąpić przeciwko nim bez prowokacji, ale możemy pozbyć się części naturalnej konkurencji o pożywienie.$B$BKażda zabita hydra grzęzawisk to trzy gęby mniej do wykarmienia!', 'Zabij 10 hydr grzęzawisk i wróć do Haalruna w Telredorze.', '', 'Wróć do Haalruna w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9782, 'plPL', 'Martwe Grzęzawisko', 'Od jakiegoś czasu żyję wśród anachoretów z Telredoru, $N, i przez ten czas dość dobrze poznałem moczary. Ostatnio zacząłem dostrzegać niepokojącą zmianę na ziemiach na północnym wschodzie.$B$BNiemal całe tamtejsze życie zaczęło więdnąć i umierać, pozornie bez żadnego powodu. Mam kilka pomysłów, co może się dziać, ale to niewiele więcej niż domysły. Gdybyś $gprzyniósł:przyniosła; mi próbkę tamtejszej gleby, może zdołałbym rozwikłać tę zagadkę.', 'Przynieś Próbkę gleby z Martwego Grzęzawiska Obrońcy Idaarowi w Telredorze.', '', 'Wróć do Obrońcy Idaara w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9783, 'plPL', 'Nienaturalna susza', 'W próbce gleby, którą mi $gprzyniosłeś:przyniosłaś;, prawie nie ma wilgoci, $N. Jeśli nawet gleba traci wilgoć, stworzenia żyjące na Martwym Grzęzawisku muszą strasznie cierpieć.$B$BWidziałem, co się dzieje, gdy tutejsze grzybowe olbrzymy zaczynają więdnąć i umierać. Ból doprowadza je do szaleństwa i atakują wszystko, co stanie im na drodze.$B$BTe stworzenia nie mają pojęcia, co się z nimi dzieje. Nie jesteśmy w stanie ich ocalić, więc najlepsze, co możemy zrobić, to skrócić ich cierpienia.', 'Obrońca Idaar w Telredorze chce, żebyś $gzabił:zabiła; 12 uschniętych olbrzymów.', '', 'Wróć do Obrońcy Idaara w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9784, 'plPL', 'Rozpoznawanie części roślin', '', '', '', 'Wróć do Lauranny Thar\'well w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9785, 'plPL', 'Błogosławieństwa pradrzew', '$GZdobyłeś:Zdobyłaś; zaufanie Ekspedycji Cenariońskiej, $N. Czas, żebyś $gporozmawiał:porozmawiała; z pradrzewami, które sprzymierzyły się z naszą sprawą, Ashyen i Kelethem, i $gpoprosił:poprosiła; je o błogosławieństwo.$B$BZnak pradrzewa napełni cię wielką mocą. Te dary będą rosły w siłę wraz z twoją sławą wśród nas.$B$BIdź, $N, i poproś pradrzewa o błogosławieństwo.', 'Przywoływaczka wiatru Czarne Kopyto chce, żebyś $gporozmawiał:porozmawiała; z pradrzewami Ashyen i Kelethem w Schronieniu Cenariona i $guzyskał:uzyskała; ich błogosławieństwa.', '', 'Wróć do Przywoływaczki wiatru Czarne Kopyto w Schronieniu Cenariona na Moczarach Zangarskich.', 'Znak wiedzy', 'Znak wojny', '', '', 0),
(9786, 'plPL', 'Ruiny Boha\'mu', 'Zanim orkowie zdziesiątkowali mój lud, Telredor był miejscem odosobnienia dla draenejskich anachoretów i mistyków. Niewielki zakon anachoretów i obrońców opiekował się kilkoma kapliczkami w tej okolicy.$B$BPodczas wojny straciliśmy kontakt z anachoretami, którym powierzono kapliczki, zwłaszcza świątynię Boha\'mu na południowym zachodzie. Słyszałem, że w okolicy osiedliło się plemię Zagubionych, które może nawet korzystać z ruin. Odwiedź Ruiny Boha\'mu i opowiedz mi, co tam znajdziesz.', 'Anachoreta Ahuurn w Telredorze chce, żebyś $gzbadał:zbadała; Ruiny Boha\'mu.', 'Zbadaj Ruiny Boha\'mu', 'Wróć do Anachorety Ahuurna w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9787, 'plPL', 'Idole z Dzikich Mokradeł', 'Z tego, co mi $gopowiedziałeś:opowiedziałaś; o swoich obserwacjach w Ruinach Boha\'mu, wynika, że to plemię Zagubionych powróciło do czczenia duchów zwierząt. Zanim się do nich zbliżymy, musimy więcej wiedzieć o ich wierzeniach.$B$BWróć do Wioski Dzikich Mokradeł i dyskretnie zbierz trochę ich idoli, żebym mógł je zbadać. Staraj się ich nie rozzłościć, $N, bo to może zaszkodzić naszym szansom na nawiązanie z nimi kontaktu.', 'Zbierz 6 idoli z Dzikich Mokradeł i zanieś je Anachorecie Ahuurnowi w Telredorze.', '', 'Wróć do Anachorety Ahuurna w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9788, 'plPL', 'Wilgotne, ciemne miejsce', 'Wkrótce po ucieczce od plemienia Cienistych Mokradeł zaszyłem się w jaskini na południe od ich wioski. Nie miałem pojęcia, że o tę jaskinię walczą bagienne bestie i grzybowi ludzie!$B$BMusiałem uciekać w pośpiechu i zostawiłem tam skrzynkę z całym moim doczesnym dobytkiem.$B$BUdało mi się wymknąć z Cienistych Mokradeł z moimi rzeczami, a potem, jak na ironię, straciłem je tak szybko. Jeśli zechcesz mi je przynieść, dam ci jeden z moich własnych przedmiotów. Co ty na to, $N?', 'Poszukaj Rzeczy Ikeyena w jaskini na południe od Cienistych Mokradeł. Zanieś je Ikeyenowi w Schronieniu Cenariona na Moczarach Zangarskich.', '', 'Wróć do Ikeyena w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9790, 'plPL', 'Przejrzyste skrzydła', 'Życie w tak odludnym miejscu nauczyło nas wykorzystywać wszystko, co jest pod ręką. Oczywiście najpierw trzeba się oduczyć myślenia o tym, skąd pochodzą niektóre z tych materiałów.$B$BOdkryłem, że skrzydła żądlarzy cienistej poświaty świetnie nadają się do impregnacji. Są mocne, cienkie i giętkie.$B$B<Haalrun chichocze.>$B$BWidzę twoją minę. Jak mówiłem, trzeba czasu, żeby przywyknąć do tej myśli. Jeśli i tak będziesz w terenie, może przyniesiesz mi trochę tych skrzydeł?', 'Haalrun w Telredorze chce, żebyś $gprzyniósł:przyniosła; mu 8 przejrzystych skrzydeł dowolnego gatunku świetlików z Moczarów Zangarskich.', '', 'Wróć do Haalruna w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9791, 'plPL', 'Groźne bagiennokły', 'Podczas wojny orków z moim ludem zbieracze rzadko opuszczali Telredor, bojąc się ataku albo niewoli. Teraz wyprawiamy się częściej, ale moczary wcale nie są mniej niebezpieczne.$B$BWygląda na to, że płaszczki Otchłani w ostatnich miesiącach zrobiły się śmielsze. Nie wiem, czy ma to związek z większą konkurencją o ich zwykłą zdobycz, ale regularnie atakują nasze grupy zbieraczy. Jeśli przetrzebimy ich szeregi w okolicach Telredoru, może nauczą się zostawiać nas w spokoju.', 'Zabij 10 bagiennokłych rozpruwaczy i wróć do Noraani w Telredorze.', '', 'Wróć do Noraani w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9792, 'plPL', 'Wiadomość dla Telaar', '$GOkazałeś:Okazałaś; się $guczciwy:uczciwa; w naszych sprawach, $N, i to w czasach, gdy trudno zdobyć zaufanie mojego ludu.$B$BDuża grupa moich braci zamieszkała w starym draenejskim mieście Telaar w Nagrandzie, na południu. Żeby dotrzeć do Telaar, idź drogą na południe do Nagrandu, a potem kieruj się na południowy wschód, aż dotrzesz do urwisk na wschód od Oshu\'gun.$B$BKażdy, kto nam pomógł, tak jak ty, będzie mile widziany wśród mieszkańców Telaar.$B$BOdszukaj Nahuuda i powiedz mu, że $gzdobyłeś:zdobyłaś; moje zaufanie.', 'Porozmawiaj z Nahuudem w Telaar w Nagrandzie.', '', '', '', '', '', '', 0),
(9793, 'plPL', 'Los Tuurem', 'Poszukiwania sojuszników przez Proroka Velena dodały odwagi draenei pozostałym w Rubieży i sami też zaczęli szukać. Wojna Legionu przeciw mojemu ludowi wygnała nas z naszych miast i świątyń, ale nie zatarła śladów naszej cywilizacji.$B$BTuurem, mój dawny dom w Puszczy Terokkar, było jednym z pierwszych miast zajętych przez orków. Już zbyt długo nie miałem wieści o jego losie. Zanieś ten list Andarlowi w Forcie Alleriańskim w Puszczy Terokkar i zobacz, czego zdołasz się dowiedzieć.', 'Zanieś List obrońcy Idaara Andarlowi w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(9794, 'plPL', 'Nie czas na ciekawość', '$N, mam do ciebie prośbę. Normalnie zrobiłbym to sam, ale mam już ręce więcej niż pełne roboty.$B$BMam wspólnika imieniem Kialon w Sylvanaar w Górach Klingi na północy. Spodziewa się wkrótce wieści ode mnie, choć podejrzewam, że nie spodoba mu się to, co mam do powiedzenia.$B$BJeśli dostarczysz mu moją odpowiedź, będę ci wdzięczny. Muszę jednak nalegać – i to bardzo ważne – żebyś nie $gpróbował:próbowała; czytać tego listu. Jest przeznaczony tylko dla oczu Kialona.', 'Dostarcz list Timothy\'ego Kialonowi w Sylvanaar w Górach Klingi.', '', '', '', '', '', '', 0),
(9795, 'plPL', 'Zagrożenie ze strony ogrów', 'Jakby mało było nag i ich sojuszników, ogry rozszerzają swoje wpływy na moczarach. Podbiły już większość okolic na północnym zachodzie i nie zostało nam wiele strefy buforowej.$B$BNa miejsce każdego zabitego przychodzi kilku kolejnych. Nie wiem, jak długo zdołamy utrzymać Zabra\'jin, kiedy postanowią zaatakować. Ruszaj na północ, w góry, do orczej Warowni Władców Gromu, i powiadom Nekthara o naszym położeniu. Każda pomoc, jaką może wysłać, będzie bardzo mile widziana.', 'Udaj się do Warowni Władców Gromu w Górach Klingi i porozmawiaj z Nektharem.', '', '', '', '', '', '', 0),
(9796, 'plPL', 'Wieści z Moczarów Zangarskich', 'Nie tylko łowca cieni Denjai czeka na raport ode mnie. Mokasa w Warowni Kamieniołamaczy w Puszczy Terokkar chce usłyszeć o naszych postępach, zwłaszcza że większość jej posłańców przechodzi tędy.$B$BProsiła, żebym dał znać, gdy Posterunek Bagiennego Szczura zostanie ukończony. Jeśli nie masz nic przeciwko zaniesieniu jej tych wieści, będę ci bardzo wdzięczny. Może i już działamy, ale jeszcze wiele zostało do zrobienia.$B$BŻeby dotrzeć do Warowni Kamieniołamaczy, idź drogą na południe z Moczarów Zangarskich do Puszczy Terokkar i dalej, za Tuurem.', 'Porozmawiaj z Mokasą w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(9797, 'plPL', 'Posiłki dla Garadaru', '<Posłaniec, wciąż łapiąc oddech, daje ci znak, żebyś $gusiadł:usiadła;.>$B$BMogą nie przetrwać! Biegnij do Garadaru tak szybko, jak cię nogi poniosą.$B$B<Widząc twoje nierozumiejące spojrzenie, posłaniec wyjaśnia.>$B$BTo siedziba Mag\'harów, leży na południu, w Nagrandzie. Wyjdź z moczarów południową drogą, na pierwszym rozwidleniu skręć na wschód i szukaj dużej osady nad jeziorem.$B$BOdszukaj tam naszego dowódcę, Kapitana Kroghana, i zaoferuj mu wszelką pomoc, jakiej możesz udzielić. Garadar nie może upaść!', 'Porozmawiaj z Kapitanem Kroghanem w Garadarze w Nagrandzie.', '', '', '', '', '', '', 0),
(9801, 'plPL', 'Zbieranie składników', 'Mam przeczucie, że ci Zagubieni mogą nie przyjąć dobrze draeneja, ale powitaliby arakkoa. Potrafię sporządzić miksturę, dzięki której na krótko przybierzesz postać arakkoa. Wymaga kilku składników, których nie da się przechowywać i trzeba ich użyć w ciągu kilku godzin od zebrania.$B$BMusisz mi przynieść garść oczu nietoperzy-zarodników i trochę macek mokradłowych kroczaków. Oba gatunki żyją w dziczy wokół Telredoru.', 'Anachoreta Ahuurn w Telredorze chce, żebyś $gprzyniósł:przyniosła; mu 4 oczy nietoperza-zarodnika i 4 macki mokradłowego kroczaka.', '', 'Wróć do Anachorety Ahuurna w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9802, 'plPL', 'Rośliny Moczarów Zangarskich', 'Z jezior Moczarów Zangarskich powoli ubywa wody. Nie wiemy dokładnie dlaczego, ale wiemy, że wielu gatunkom roślin grozi wyginięcie.$B$BJako katalogująca w ekspedycji mam za zadanie śledzić i rozpoznawać te rośliny, żebyśmy lepiej zrozumieli, co się z nimi dzieje.$B$BJeśli chcesz pomóc, przynoś mi niezidentyfikowane części roślin. Zielarze mogą je zbierać prosto z ziemi, a tutejsze stworzenia z bagien też mogą mieć przy sobie części roślin.', 'Przynieś 10 niezidentyfikowanych części roślin Laurannie Thar\'well w Schronieniu Cenariona na Moczarach Zangarskich.', '', 'Wróć do Lauranny Thar\'well w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9803, 'plPL', 'Posłaniec do Dzikich Mokradeł', 'Nadszedł czas, byśmy przygarnęli plemię Dzikich Mokradeł i pokazali im, że Światłość ich nie opuściła. Weź miksturę, którą przygotowałem, i zabierz ją do Ruin Boha\'mu.$B$BGdy dotrzesz do ruin, wypij miksturę, by przybrać postać jednego z ich ptasich duchów. Porozmawiaj ze Starszym Kurutim i powiedz mu, że draenei są gotowi powitać jego lud jako dawno utraconych braci.', 'Wypij Eliksir Ahuurna w Ruinach Boha\'mu. Porozmawiaj ze Starszym Kurutim, gdy będziesz w postaci arakkoa.', '', 'Wróć do Anachorety Ahuurna w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9806, 'plPL', 'Żyzne zarodniki', 'Nietoperze-zarodniki i bagienne wędrowce, krążąc wokół wysokołodygowych grzybów na moczarach, zbierają na odnóżach żyzne zarodniki.$B$BJak widzisz, jesteśmy niskim ludem, więc nasze możliwości zbierania tych zarodników są ograniczone. Odszukaj nietoperze-zarodniki i bagienne wędrowce i zbierz żyzne zarodniki. Cały Sporeggar będzie twoim dłużnikiem.', 'Gshaff chce, żebyś $gzebrał:zebrała; 6 żyznych zarodników od różnych nietoperzy-zarodników i bagiennych wędrowców z Moczarów Zangarskich. Po wykonaniu zadania wróć do Gshaffa w Sporeggarze.', '', 'Wróć do Gshaffa w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9807, 'plPL', 'Więcej żyznych zarodników', '', '', '', 'Wróć do Gshaffa w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9808, 'plPL', 'Świecące kapelusze', 'Widziałem, jak twoi pobratymcy wymieniają błyszczące okrągłe kawałki metalu na potrzebne im rzeczy. Nie różnimy się aż tak bardzo. My jako pieniędzy używamy błyszczących okrągłych grzybów.$B$BŚwiecące kapelusze rosną na moczarach wszędzie, trzeba tylko wiedzieć, jak je zerwać z ziemi, żeby ich nie zniszczyć. Nauczę cię tego, jeśli obiecasz, że przyniesiesz nam trochę do naszych zapasów. Co ty na to, $N?', 'Przynieś 10 świecących kapeluszy Msshi\'fnowi w Sporeggarze na Moczarach Zangarskich.', '', 'Wróć do Msshi\'fna w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9809, 'plPL', 'Więcej świecących kapeluszy', '', '', '', 'Wróć do Msshi\'fna w Sporeggarze na Moczarach Zangarskich.', '', '', '', '', 0),
(9814, 'plPL', 'Grzyby pękacze, mon!', 'Lubisz grzyby, mon? Tu na Moczarach Zangarskich jest jeden potężny, rośnie całkiem blisko Zabra\'jin.$B$BAle musisz uważać, mon. Nie bez powodu nazywają go pękaczem. Jak podejdziesz za blisko bez odpowiednich środków ostrożności, wybuchnie ci prosto w twarz! Puff! Prosto w chmurę trujących zarodników.$B$BUżywam ich do odczytywania wróżb, ale już prawie mi się skończyły.', 'Przynieś znachorowi Tor\'gashowi 6 grzybów pękaczy.', '', 'Wróć do znachora Tor\'gasha w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9816, 'plPL', 'Widział ktoś coś takiego?', 'Na tych moczarach brakuje jednej rzeczy, mon! Nie ma tu murloków.$B$BNie martw się, mon, mam plan, jak temu zaradzić. Widzisz tam Gulgota i Bulgota? Zamierzam obdarować Zagubionych murlokami!$B$BZabierz tę klatkę do Wioski Sztyletowych Mokradeł i wypuść je w północno-wschodniej grupie chat. Wiesz, że nie mogę ryzykować, dając ci Gulgota i Bulgota, ale dam ci klatkę pełną kolorowych młodych murloków. Postaw ją tylko na płaskiej skale, którą tam znajdziesz, i otwórz drzwiczki!', 'Zabierz Klatkę z murlokami i postaw ją na płaskiej skale w pobliżu Wioski Sztyletowych Mokradeł.', '', 'Wróć do znachora Tor\'gasha w Zabra\'jin na Moczarach Zangarskich.', 'Wypuść murloki w Wiosce Sztyletowych Mokradeł', '', '', '', 0),
(9817, 'plPL', 'Przywódczyni Krwawej Łuski', 'Ekspedycja Cenariońska niniejszym wyznacza nagrodę za Rajis Fyashe, przywódczynię nag z Krwawej Łuski. Tę nagę czarodziejkę ostatnio widziano nad Wężowym Jeziorem, w północnej części Moczarów Zangarskich.$B$BKrwawą Łuskę należy uważać za niezwykle niebezpieczną, a do jej przywódczyni zbliżać się z największą ostrożnością.$B$BChętni do odebrania nagrody powinni zgłosić się do Strażnika Hamoota w Schronieniu Cenariona.', 'Zabij Rajis Fyashe nad Wężowym Jeziorem i wróć po nagrodę do Strażnika Hamoota w Schronieniu Cenariona na Moczarach Zangarskich.', '', 'Wróć do Strażnika Hamoota w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9820, 'plPL', 'POSZUKIWANY: Herszt Grog\'ak', 'Poszukiwany żywy lub martwy: Herszt Grog\'ak, nadzorca wyrębu grzybów prowadzonego przez Ango\'rosh.$B$BTen osiłek i jego kompani z toporami odpowiadają za ścinanie grzybów na północ od miasta. Jeśli nikt go nie powstrzyma, on i jego banda wyrąbią sobie drogę aż pod mury Zabra\'jin.$B$B$gTen, kto:Ta, która; dostarczy głowę Herszta Grog\'aka łowcy cieni Denjaiowi, otrzyma sowitą nagrodę.', 'Przynieś Głowę herszta Grog\'aka łowcy cieni Denjaiowi w Zabra\'jin.', '', 'Wróć do łowcy cieni Denjaia w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9822, 'plPL', 'Nadciągający atak', 'Położenie wyrębu grzybów, który prowadzą ogry, nie może być przypadkowe. Nie mogę się oprzeć podejrzeniu, że szykują atak na Zabra\'jin.$B$BMuszę wiedzieć na pewno, $N. Ogry mają kolejną placówkę na północnym zachodzie, na Ziemiach Ango\'rosh. Jeśli szykują się do ataku, znajdą się tam dowody ich planów. Idź tam, $N, i przeszukaj obóz pod kątem śladów ich zamiarów. Wróć do mnie ze wszystkim, co wyda ci się podejrzane.', 'Przynieś Plany ataku Ango\'rosh łowcy cieni Denjaiowi w Zabra\'jin.', '', 'Wróć do łowcy cieni Denjaia w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9823, 'plPL', 'My albo oni', 'Żeby położyć kres zagrożeniu ze strony Ango\'rosh, musimy zabić ich przywódcę, Nadrządcę Krwiopięść. Ale zrobimy coś więcej. Zrobimy z nadrządcy i jego popleczników przykład dla innych.$B$BIdź do Warowni Ango\'rosh i rozpraw się z naszymi wrogami. Warownia mieści się w jaskini na małej wyspie na północny zachód od Zabra\'jin. Za Obozem Ango\'rosh zobaczysz most z powalonego grzyba.$B$BNie okazuj litości, $N. Oni z pewnością nie oszczędziliby nikogo z nas.', 'Zabij Nadrządcę Krwiopięść, 10 mocarzy Ango\'rosh i 10 pożeraczy dusz Ango\'rosh, a potem zamelduj się u łowcy cieni Denjaia w Zabra\'jin.', '', 'Wróć do łowcy cieni Denjaia w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9827, 'plPL', 'Uschnięta podstawka', 'Uważne oględziny podstawki ujawniają kilka wgłębień, w których kiedyś mogło coś tkwić. Ta obca masa grzybni stanowi nie lada zagadkę. Daleko jej do zdrowia, ale nie masz pojęcia, jaką funkcję mogłaby normalnie pełnić.$B$BByć może ktoś, kto lepiej zna mieszkańców Moczarów Zangarskich, powie ci o niej więcej.', 'Zanieś Uschniętą podstawkę Ruamowi w Telredorze na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9828, 'plPL', 'Uschnięta podstawka', 'Uważne oględziny podstawki ujawniają kilka wgłębień, w których kiedyś mogło coś tkwić. Ta obca masa grzybni stanowi nie lada zagadkę. Daleko jej do zdrowia, ale nie masz pojęcia, jaką funkcję mogłaby normalnie pełnić.$B$BByć może ktoś, kto lepiej zna mieszkańców Moczarów Zangarskich, powie ci o niej więcej.', 'Zanieś Uschniętą podstawkę Reavijowi na Posterunku Bagiennego Szczura na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9830, 'plPL', 'Jad żądlarzy', 'Kiedy rozmawiam z draenei, często mam wrażenie, że uważają się za oderwanych od swojego otoczenia. Wielu z nich zdaje się litować nad moimi braćmi, Złamanymi, którzy według nich coś utracili.$B$BMy, Złamani, być może utraciliśmy skłonność ku Światłości, ale nasze doświadczenia zbliżyły nas do ziemi.$B$BMój lud dostrzega okazje tam, gdzie mało który draenei je widzi. Weźmy na przykład jad krwiopijców błędnych ogników, które żyją na południu i zachodzie. Ma mnóstwo zastosowań, od polowania po leczenie.', 'Przynieś 6 porcji jadu krwiopijcy błędnych ogników Puluu w Przystani Orebor.', '', 'Wróć do Puluu w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', 0),
(9834, 'plPL', 'Naturalny pancerz', 'Maktu zawsze widzi draeneja w błyszczącej zbroi już z daleka, nawet na tym mrocznym bagnie!$B$BMaktu chce się z nich śmiać, ale potem przypomina sobie, że byli dobrzy dla Kurenai, i chce ich nauczyć, jak Kurenai robią zbroje.$B$BCiemne, łuskowate skóry mokradłoszponych tłukaczy dają jedne z najlepszych zbroi, jakie Maktu kiedykolwiek nosił. Jeśli $N przyniesie Maktu trochę tych skór mokradłoszponych tłukaczy z głębin Wężowego Jeziora, Maktu chętnie podzieli się swoimi zbrojami.', 'Przynieś 8 skór mokradłoszponego tłukacza Maktu w Przystani Orebor.', '', 'Wróć do Maktu w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', 0),
(9835, 'plPL', 'Najazd Ango\'rosh', 'Ta niewielka grupa Złamanych, którą tu widzisz, to misja z większej osady w Nagrandzie. Kurenai, jak siebie nazywamy, to Złamani, którzy pragną ponownie połączyć się z naszymi draenejskimi braćmi.$B$BMoja grupa przybyła tu, by zacieśnić więzi Kurenai z draenei z Telredoru.$B$BJeśli ogry Ango\'rosh dopną swego, ta świątynia długo już nie przetrwa. Oczyściły Wyrąbane Trzęsawisko z wyniosłych grzybów i podchodzą coraz bliżej naszego schronienia. Jeśli chcesz nazywać się naszym przyjacielem, pomóż nam walczyć z tym wrogiem.', 'Zabij 10 ogrów Ango\'rosh i 5 szamanów Ango\'rosh, a potem wróć do Ikutiego w Przystani Orebor.', '', 'Wróć do Ikutiego w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', 0),
(9839, 'plPL', 'Nadrządca Krwiopięść', 'Sercem każdego plemienia ogrów jest jego przywódca. Bez przywództwa organizacja Ango\'rosh się rozpadnie, a oni zaczną walczyć między sobą o to, kto obejmie władzę.$B$BChoć widujemy ogry w tej okolicy, ich prawdziwa siła skupia się w Warowni Ango\'rosh na północnym zachodzie. Mieści się w jaskini na małej wyspie połączonej z moczarami powalonym grzybem.$B$BIdź tam i pokonaj Nadrządcę Krwiopięść. To powinno zapewnić nam zasłużoną chwilę wytchnienia.', 'Ikuti chce, żebyś $gzabił:zabiła; Nadrządcę Krwiopięść i 10 mocarzy Ango\'rosh. Po wykonaniu zadania wróć do Przystani Orebor.', '', 'Wróć do Ikutiego w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', 0),
(9841, 'plPL', 'Użądlić żądlarzy', 'Nie da się pracować przy tym piekielnym bzyczeniu! Słyszysz to?$B$BNie mogę tego wyrzucić z głowy! I dokładnie wiem, co robi ten hałas. To te przeklęte krwiopijce błędnych ogników! Dźwięk zawsze dochodzi z południa i zachodu od wioski.$B$BSą za duże, żeby je pacnąć, rozdeptać albo odgonić. Jedyny sposób, żeby przerwać to piekielne brzęczenie, to je zabić. Nie obchodzi mnie, jak to zrobisz, $N, byle by ucichły!', 'Zabij 8 krwiopijców błędnych ogników i wróć do Gambarinki w Zabra\'jin.', '', 'Wróć do Gambarinki w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9842, 'plPL', 'Najostrzejsze ostrza', 'Wilgoć moczarów dała się we znaki moim metalowym narzędziom. Obróbka drewna stała się przez to o wiele trudniejsza, niż powinna, więc zrezygnowałem z metalowych ostrzy.$B$BOkazuje się, że bagiennokłym siekaczom, które żyją na południe i zachód od miasta, wyrastają ostrza ostrzejsze niż jakakolwiek stal, jaką kiedykolwiek miałem. Do tego nie rdzewieją i się nie ścierają. Trochę trudno je przymocować do rękojeści, ale chyba już wiem, jak to zrobić. Będę wdzięczny za każde ostrze, które mi przyniesiesz.', 'Przynieś 10 ostrzy bagiennokłego siekacza Gambarince w Zabra\'jin.', '', 'Wróć do Gambarinki w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9845, 'plPL', 'Wędkarska konkurencja', 'Co za ulga znaleźć się gdzieś, gdzie jest woda, po wędrówce przez pustkowia Półwyspu Piekielnego Ognia. Martwiłam się, że w Rubieży nie będzie żadnych porządnych łowisk.$B$BTeraz cieszę się, że przytaszczyłam ze sobą sprzęt wędkarski. Przeważnie ryby dobrze biorą, z wyjątkiem tych paskudnych mokradłoszponych tłukaczy w Wężowym Jeziorze.$B$BNie dość, że płoszą ryby, to jeszcze są na tyle bezczelne, że zrywają mi przynętę prosto z haczyka. Więcej czasu spędzam na zakładaniu przynęty niż na łowieniu czegokolwiek!', 'Zabij 10 mokradłoszponych tłukaczy i wróć do Zurjayi w Zabra\'jin.', '', 'Wróć do Zurjayi w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9846, 'plPL', 'Duchy Dzikich Mokradeł', 'O najpotężniejszym plemieniu Zagubionych na moczarach, plemieniu Dzikich Mokradeł, mówi się, że ma potężne czary. Być może w tych plotkach nie ma ziarna prawdy, ale nie mogę lekceważyć niczego, co mogłoby mi pomóc przywoływać duchy tego świata.$B$BOdszukaj mistyków, łowców i druidów z Dzikich Mokradeł, $N, i zdobądź ich totemy. Wszystko, co muszę wiedzieć, powinno się dać odczytać z rzeźbień.', 'Przynieś 10 ochronnych totemów z Dzikich Mokradeł Jasnowidzce Janidi w Zabra\'jin.', '', 'Wróć do Jasnowidzki Janidi w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9847, 'plPL', 'Duchowy sojusznik?', 'Musimy się dowiedzieć, jaką moc ma ten wężowy duch z Dzikich Mokradeł i czy da się go nagiąć do naszej woli. Wyobraź sobie, co mogłabym zrobić, mając na rozkazy moc ducha z Rubieży!$B$BWeź ze sobą ten totem i idź do podnóża schodów prowadzących do Ruin Boha\'mu. Wbij totem w ziemię, a on powinien zrobić resztę. Duch nie powinien się zorientować, kto użył totemu, dopóki się nie objawi.', 'Zanieś Totem z Dzikich Mokradeł do podnóża schodów w Ruinach Boha\'mu i wbij go w ziemię. Przekaż swoje spostrzeżenia Jasnowidzce Janidi w Zabra\'jin.', '', 'Wróć do Jasnowidzki Janidi w Zabra\'jin na Moczarach Zangarskich.', 'Przyzwij wężowego ducha', '', '', '', 0),
(9848, 'plPL', 'Sekrety Sztyletowych Mokradeł', 'Robale, robale, robale! Moczary są ich pełne, a moi towarzysze najwyraźniej mają na ich punkcie obsesję.$B$BA ja mam dość robali! Moją uwagę przykuło coś o wiele ciekawszego. Na zachodzie jest wioska Zagubionych, którzy nazywają siebie plemieniem Sztyletowych Mokradeł.$B$BCałe plemię składa się z wyspecjalizowanych zabójców. Zauważyłem, że mieszają i stosują wyjątkowo silną truciznę. Umieram z ciekawości, żeby dowiedzieć się o niej więcej, ale do tego potrzebuję kopii przepisu i fiolki z próbką.', 'Przynieś Podręcznik trucizn ze Sztyletowych Mokradeł i Fiolkę trucizny ze Sztyletowych Mokradeł Timothy\'emu Danielsowi w Przystani Orebor.', '', 'Wróć do Timothy\'ego Danielsa w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', 0),
(9875, 'plPL', 'Nieskatalogowany gatunek', 'Lauranna musiała przeoczyć tę roślinę. Masz pewność, że $godkryłeś:odkryłaś; gatunek, którego Lauranna jeszcze nie skatalogowała. Najlepiej pokaż go jej i zobacz, co o nim sądzi.', 'Zanieś Nieskatalogowany gatunek Laurannie Thar\'well w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9876, 'plPL', 'Nieudany wypad', 'Wysłałam niewielką grupę naszych druidów, żeby zbadali odpływ, który $godkryłeś:odkryłaś; w Wężowym Jeziorze. Mieli wrócić wkrótce potem. Nie trzeba mówić, że nie wrócili.$B$BJesteś jednym z naszych najzdolniejszych sojuszników. Proszę cię, odszukaj ich i dowiedz się, co się z nimi stało.', 'Ysiel Pieśń Wiatru chce, żebyś $gposzukał:poszukała; śladów druidów Ekspedycji Cenariońskiej w pobliżu wejścia do Zbiornika Żmijokolców na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9894, 'plPL', 'Ochrona wartowników', 'W czasie swoich wędrówek być może $gspotkałeś:spotkałaś; niektórych wartowników ekspedycji. To oni wykonują większość pracy w terenie: opisują niezwykłych mieszkańców moczarów, zbierają próbki i nawiązują kontakt z rozumnymi gatunkami.$B$BBezpieczeństwo wartowników jest najważniejsze, $N. Musieliśmy odwołać wartowników wysłanych na zbadanie Pieczary Funggor na południu z powodu ataków bagiennych bestii. Strażnik Hamoot uważa, że zabicie ich przywódcy, Lorda Klaqa, szybko położy kres atakom.', 'Zabij Lorda Klaqa i wróć do Przywoływaczki wiatru Czarne Kopyto w Schronieniu Cenariona.', '', 'Wróć do Przywoływaczki wiatru Czarne Kopyto w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9895, 'plPL', 'Zachwiana równowaga', 'Czy $gprzyjrzałeś:przyjrzałaś; się uważnie otoczeniu, $N? To chora kraina, która walczy o zachowanie równowagi i przegrywa tę walkę.$B$BJeśli wiesz, gdzie patrzeć, dostrzeżesz objawy. Osobniki niektórych gatunków szybko przerastają swoich pobratymców i stają się bardziej agresywne.$B$BDobrym przykładem takiego niekontrolowanego wzrostu jest bagienny wędrowiec Bagnobicz. Jeśli chcesz zobaczyć go na własne oczy, wystarczy, że pójdziesz do cieków wodnych na południe od schronienia.$B$BBądź $ggotów:gotowa; się bronić. To stworzenie nie zna litości.', 'Odszukaj Bagnobicza i rozpraw się z nim, a potem wróć do Lethyna Księżycowego Ognia w Schronieniu Cenariona.', '', 'Wróć do Lethyna Księżycowego Ognia w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(9896, 'plPL', 'Zguba Czarnego Żądła', 'Na płonący pępek Khaz\'gorotha, ale tu gorąco! Nie dziwię się pierwszej wyprawie, że się stąd wyniosła, ale wszyscy wiedzą, że to nie upał ich przegonił. O nie, to było Czarne Żądło, choć się do tego nie przyznają.$B$BObozowali tuż na południe od świecących draenejskich wież na zachodzie, zaraz na północ od Wioski Dzikich Mokradeł, kiedy znikąd pojawia się ta olbrzymia osa i atakuje! Nie mogę się doczekać ich min, kiedy przywiozę żądło tego stwora do Żelaznej Kuźni i im je pokażę!', 'Przynieś Żądło Czarnego Żądła Poszukiwaczowi Conallowi w Telredorze.', '', 'Wróć do Poszukiwacza Conalla w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(9898, 'plPL', 'Nic tak nie mówi „kocham cię” jak wielkie żądło', 'Będzie moja. O tak, będzie moja.$B$BCzyż Magasha nie jest najpiękniejszą trollicą, jaką kiedykolwiek $gwidziałeś:widziałaś;? Muszę znaleźć sposób, żeby zdobyć jej serce. Jasne, ma oko na Zuraia, ale to się zaraz zmieni. Już mój niezawodny plan o to zadba.$B$BPotrzebuję tylko sposobu, żeby pokazać moje wyjątkowe umiejętności łowieckie, i tu wkraczasz ty, przyjacielu. Po okolicy na południe od świecących draenejskich wież na zachodzie grasuje olbrzymia osa bagienna zwana Czarnym Żądłem. Przynieś mi jej żądło, a ja zrobię resztę.', 'Przynieś Żądło Czarnego Żądła Reavijowi na Posterunku Bagiennego Szczura.', '', 'Wróć do Reavija na Posterunku Bagiennego Szczura na Moczarach Zangarskich.', '', '', '', '', 0),
(9899, 'plPL', 'Niedokończona robota', 'Ktoś musi znaleźć sposób, żeby przywołać Reavija do rozsądku! Zaniedbuje obowiązki i zamiast tego całą energię poświęca na zwracanie mojej uwagi. Próbowałam go ignorować i kazać mu przestać. Nic nie działa.$B$BDopóki mu nie przejdzie, to ja muszę po nim sprzątać. Miał się rozprawić z Zarodnikoskrzydłym, ale założę się, że potwór ma się świetnie. Jeśli masz czas, może pójdziesz do zachodniej części Martwego Grzęzawiska i zabijesz tego nietoperza? A ja tymczasem zajmę się Reavijem.', 'Magasha na Posterunku Bagiennego Szczura chce, żebyś $gzabił:zabiła; Zarodnikoskrzydłego.', '', 'Wróć do Magashy na Posterunku Bagiennego Szczura na Moczarach Zangarskich.', '', '', '', '', 0),
(9902, 'plPL', 'Postrach Jeziora Błędnych Ogników', 'Wędrówka przez ziemie opanowane przez nagi pokazała mi okrutną prawdę o tym, jak traktuje się moich mniej szczęśliwych braci. Nad Jeziorem Błędnych Ogników, na południowym zachodzie, widziałem wyjątkowo złośliwego nadzorcę, który prowadził śmiertelną grę. Wysyła niewolników na wyspy na Jeziorze Błędnych Ogników, kiedy wie, że Grozoszpon, olbrzymi bagiennik, szykuje się do żeru.$B$BNie muszę opisywać, co z tego wynika. Jest nas za mało, żeby stawić czoła nagom bezpośrednio, ale możemy odebrać im rozrywkę, zabijając ich pupila.', 'Zabij Grozoszpona i wróć do Puluu w Przystani Orebor.', '', 'Wróć do Puluu w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', 0),
(9903, 'plPL', 'Największy ze wszystkich', '$GRozprawiłeś:Rozprawiłaś; się z większością małych hydr, ale wątpię, żeby twój pokaz zrobił wrażenie na Mrageshu. To przebiegła, dzika bestia i w swoim czasie dała się we znaki niejednemu wędkarzowi.$B$BZamierzam być ostatnią osobą, której będzie się naprzykrzał. Na pewno ukrywa się głęboko w wodach Wężowego Jeziora, na północnym wschodzie. To już przeszłość, tylko on jeszcze o tym nie wie.', 'Zabij Mragesha i wróć do Zurjayi w Zabra\'jin.', '', 'Wróć do Zurjayi w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9904, 'plPL', 'W pogoni za Grozoszponem', 'Złowiłam już każdy gatunek ryby, jaki żyje na moczarach, ale jeden wciąż mi się wymyka. Jasne, łowiłam węgorze i mułopłetwe szałowce. Ale kiedy ostatnio byłam na jednej z wysp na Jeziorze Błędnych Ogników, na haczyk złapał się olbrzymi bagiennik, który zerwał mi żyłkę i uciekł.$B$BNazywają go Grozoszponem i nie spocznę, dopóki nie zginie. Jest za duży, żeby złowił go jakikolwiek rybak, więc chyba trzeba go będzie zabić po staremu.', 'Zabij Grozoszpona i wróć do Zurjayi w Zabra\'jin.', '', 'Wróć do Zurjayi w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(9905, 'plPL', 'Zemsta Maktu', 'Kiedy ostatnio Maktu polował na hydry nad Wężowym Jeziorem dla skór, zaatakowała go największa hydra, jaką kiedykolwiek widział. Maktu sięgnął po włócznię, ale było za późno. Ledwie zdążył uciec, zanim stał się pożywieniem hydry.$B$BKto wie? Może następnym razem Maktu nie mieć tyle szczęścia. Maktu chce tam być, żeby następnego razu nie było. Pomożesz Maktu zemścić się na Mrageshu?', 'Odszukaj i zabij Mragesha, a potem wróć do Maktu w Przystani Orebor.', '', 'Wróć do Maktu w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', 0),
(9911, 'plPL', 'Hrabia moczarów', 'Ta zakrwawiona żuwaczka pochodzi od niewiarygodnie wielkiego stworzenia. Płaszczka Otchłani, do której należała, musi być największą, jaką kiedykolwiek widziano na Moczarach Zangarskich. Sądząc po stanie żuwaczki, hrabia porzucił dietę z padliny na rzecz żywego mięsa.$B$BEkspedycja Cenariońska na pewno byłaby zainteresowana takim okazem. Wartowniczka Leesa\'oh ma niewielki obóz na zachód od Grani Quagg.', 'Zanieś Żuwaczkę „Hrabiego” Unguli Wartowniczce Leesa\'oh w placówce cenariońskiej na Moczarach Zangarskich.', '', '', '', '', '', '', 0),
(9919, 'plPL', 'Sporeggar', 'Masz dobre serce, $N. Nie jak niektórzy inni, których spotkałem.$B$B$GPowinieneś:Powinnaś; poznać resztę mojego ludu; będą ci bardzo wdzięczni za pomoc. Zanieś te worki zarodników mojemu przywódcy, Msshi\'fnowi. Znajdziesz go w Sporeggarze, na północ stąd.', 'Udaj się do Sporeggaru na Moczarach Zangarskich, na północ od Jaru Wylęgu, i dostarcz Ocalone worki zarodników Msshi\'fnowi.', '', '', '', '', '', '', 0),
(9957, 'plPL', 'Co się dzieje w Gąszczu Cenariona?', 'Od dłuższego czasu nie mamy wieści od druidów z Gąszczu Cenariona w Puszczy Terokkar.$B$B$N, chciałbym, żebyś się tam $gudał:udała; i $gsprawdził:sprawdziła;, co się u nich dzieje. Można tam dotrzeć na kilka sposobów, ale najszybciej będzie iść ścieżką na południe, a gdy już znajdziesz się w puszczy, skręcić w drogę, która odchodzi na wschód od Shattrath.', 'Porozmawiaj z jednym z druidów w Gąszczu Cenariona w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10096, 'plPL', 'Ratunek dla sporeloków', 'Ikeyen opowiadał mi, co mu się przytrafiło w tamtych jaskiniach, i uważam, że to po prostu okropne!$B$BWiesz, może powinniśmy coś zrobić, żeby pomóc tym biednym sporelokom. Ikeyen mówi, że mieszkają w Pieczarze Funggor, ale niedawno wtargnęły tam bagienne bestie.$B$BMoże pójdziesz tam i spróbujesz przepędzić część tych bagiennych bestii? To zaraz na południowy zachód stąd.', 'Zabij 10 bagiennych pogłębiarzy i 10 bagiennych czyhaczy, a potem wróć do Lauranny Thar\'well w Schronieniu Cenariona na Moczarach Zangarskich.', '', 'Wróć do Lauranny Thar\'well w Schronieniu Cenariona na Moczarach Zangarskich.', '', '', '', '', 0),
(10104, 'plPL', 'Niepokój o Tuurem', 'Plotki z Tuurem są niepokojące. Jedni mówią, że ruiny miasta opanowali oszalali Złamani i Zagubieni, a jednocześnie przedsiębiorczy łowcy artefaktów kradną draenejskie relikwie.$B$BTrudno powiedzieć, które z tych plotek są prawdziwe, ale mamy obowiązek chronić ruiny najlepiej, jak potrafimy. Odszukaj Andarla w Forcie Alleriańskim w Puszczy Terokkar. Zna się trochę na magicznych relikwiach. Bardziej niż ktokolwiek inny powinien wiedzieć, co się tam dzieje.', 'Porozmawiaj z Andarlem w Forcie Alleriańskim w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10105, 'plPL', 'Wieści dla Rakorii', 'Teraz, gdy Posterunek Bagiennego Szczura jest ukończony, nasza kontrola nad drogami na moczary i z moczarów jest znacznie pewniejsza. Nasza obecność w Puszczy Terokkar jest o wiele mniej pewna. Mimo to w Warowni Kamieniołamaczy Rakoria czeka na wieści o naszych postępach.$B$BJest bystra i zdolna, $N, ale uważaj przy niej. Ma mnóstwo towarów, które chce przewozić drogami, ale nie zakładaj, że leży jej na sercu nasze dobro. Rakoria idzie tam, gdzie wierzy, że znajdzie zysk.', 'Porozmawiaj z Rakorią w Warowni Kamieniołamaczy w Puszczy Terokkar.', '', '', '', '', '', '', 0),
(10115, 'plPL', 'Występki Sztyletowych Mokradeł', 'Kurenai i draenei nie zawsze są zgodni, zwłaszcza w sprawie Zagubionych. Chętnie pomagamy tym Zagubionym, którzy sami nas szukają, ale nie będziemy się za nimi uganiać. Niektórzy draenei są zdecydowani „odkupić” ich wszystkich.$B$BBywa jednak, że nawet Zagubieni posuwają się za daleko, tak jak plemię Sztyletowych Mokradeł. W swojej wiosce na zachodzie parają się truciznami i podstępem, sztukami, które są nam z natury obce.$B$BMusimy położyć temu kres, zanim te plugawe Sztyletowe Mokradła rozszerzą swoje wpływy.', 'Zabij 3 zabójców ze Sztyletowych Mokradeł i 15 mułowców ze Sztyletowych Mokradeł.', '', 'Wróć do Ikutiego w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', 0),
(10116, 'plPL', 'Poszukiwany: Wódz Mummaki', 'Poszukiwany: Wódz Mummaki – przywódca plugawego i zdegenerowanego plemienia Zagubionych ze Sztyletowych Mokradeł, za brutalne ataki na Przystań Orebor.$B$BWódz i jego banda zabójców odpowiadają za śmierć licznych Kurenai i draenei, dlatego zbliżać się do nich powinni tylko doświadczeni wojownicy.$B$BPodróżnym zaleca się omijanie okolic Wioski Sztyletowych Mokradeł na zachód od Przystani Orebor.$B$BAby odebrać nagrodę, należy przedstawić Ikutiemu dowód śmierci wodza.', 'Przynieś Totem wodza Mummakiego Ikutiemu w Przystani Orebor.', '', 'Wróć do Ikutiego w Przystani Orebor na Moczarach Zangarskich.', '', '', '', '', 0),
(10117, 'plPL', 'Poszukiwany: Wódz Mummaki', 'Poszukiwany: Wódz Mummaki – przywódca plugawego i zdegenerowanego plemienia Zagubionych ze Sztyletowych Mokradeł, za brutalne ataki na Zabra\'jin i jego mieszkańców.$B$BWódz i jego banda zabójców odpowiadają za śmierć licznych zwiadowców i posłańców, dlatego zbliżać się do nich powinni tylko doświadczeni wojownicy.$B$BPodróżnym zaleca się omijanie okolic Wioski Sztyletowych Mokradeł na północny zachód od Zabra\'jin.$B$BAby odebrać nagrodę, należy przedstawić łowcy cieni Denjaiowi dowód śmierci wodza.', 'Przynieś Totem wodza Mummakiego łowcy cieni Denjaiowi.', '', 'Wróć do łowcy cieni Denjaia w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(10118, 'plPL', 'Wiadomość dla Sztyletowych Mokradeł', 'Ze wszystkich plemion Zagubionych na Moczarach Zangarskich plemię Sztyletowych Mokradeł jest najsprytniejsze i najbardziej agresywne. Są świetnie zorganizowani i nie ukrywają, że chcą zapanować nad pozostałymi Zagubionymi na moczarach.$B$BIch ataki już mocno dały się we znaki moim zwiadowcom i posłańcom. Nie mogę sobie pozwolić na utratę kolejnych ludzi.$B$BJeśli szybko nie zadziałamy, przejmą pełną kontrolę nad drogami i Zabra\'jin zostanie praktycznie otoczone.', 'Zabij 3 zabójców ze Sztyletowych Mokradeł i 15 mułowców ze Sztyletowych Mokradeł, a potem wróć do łowcy cieni Denjaia w Zabra\'jin.', '', 'Wróć do łowcy cieni Denjaia w Zabra\'jin na Moczarach Zangarskich.', '', '', '', '', 0),
(10355, 'plPL', 'Uschnięte ciało', 'Musimy ustalić, jak daleko rozprzestrzeniły się zniszczenia. Podstawka, którą mi $gprzyniosłeś:przyniosłaś;, pochodzi od trzęsawiskowego olbrzyma. Ich więksi, bardziej wytrzymali kuzyni, władcy trzęsawisk, powinni być odporniejsi na degenerację, która dotknęła olbrzymy.$B$BDobrze byłoby też wiedzieć, jak zmiany na Martwym Grzęzawisku wpłynęły na inne tamtejsze stworzenia.$B$BWróć na Martwe Grzęzawisko i spróbuj zdobyć próbki od władców trzęsawisk i hydr z tamtej okolicy.', 'Zbierz 5 próbek wysuszonej hydry i 5 próbek uschniętego władcy trzęsawisk i zanieś je Ruamowi w Telredorze.', '', 'Wróć do Ruama w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0),
(10459, 'plPL', 'Czczony przez Ekspedycję Cenariońską', 'Zauważyliśmy twoje osiągnięcia, $N. To, co dla nas $gzrobiłeś:zrobiłaś;, przekracza wszystko, czego oczekujemy od sojuszników.$B$BMam do ciebie szczególną prośbę, ale najpierw muszę sprawdzić twoje oddanie.', 'Ysiel Pieśń Wiatru w Schronieniu Cenariona chce, żebyś $gzdobył:zdobyła; u Ekspedycji Cenariońskiej reputację „Czczony”.', '', '', '', '', '', '', 0),
(10945, 'plPL', 'Hch\'uu i grzybowy lud', 'Miałam przyjaciółkę, która nazywała się Hch\'uu. Opowiadała mi, że trafiła do sierocińca, bo musiała uciekać przed złym grzybowym olbrzymem i się zgubiła.$B$BŚwietnie się razem bawiłyśmy, dopóki w zeszłym roku nie przyszli po nią jej pobratymcy i jej nie zabrali. Chyba mówiła, że będzie mieszkać w miejscu zwanym Sporeggar.$B$BChciałabym ją odwiedzić i zobaczyć jej grzybową wioskę. Opiekunka sierocińca powiedziała mi, że to w zachodniej części Moczarów Zangarskich, między Jeziorem Zarodnikowego Wiatru a Jeziorem Błędnych Ogników.$B$BMożemy pójść? Możemy? Proszę?!', 'Zabierz swoją podopieczną, Salandrię, do Sporeggaru na Moczarach Zangarskich. Jeśli nie będzie jej przy tobie, gdy dotrzesz na miejsce, przywołaj ją. Potem porozmawiaj z Hch\'uu.', 'Salandria zabrana do Sporeggaru', 'Wróć do Hch\'uu na Moczarach Zangarskich.', '', '', '', '', 0),
(10961, 'plPL', 'Osłona przebudzenia', 'Dawno temu relikwie, dzięki którym nauczano dróg burzowej wrony, powierzono pradawnemu druidowi.$B$BDo twojego szkolenia potrzebne są te relikwie, musimy więc zbudzić ich strażnika z drzemki.$B$BPrzygotuję miksturę, która ułatwi ci to zadanie. Potrzebne są do niej pospolite zioła, a także kwiat trzęsawisk, który zwykle rośnie na szczytach najwyższych grzybów na moczarach. Wzleć tam i zbierz je, ale uważaj, bo są bardzo delikatne i mogą gwałtownie wybuchnąć, jeśli nieostrożnie się z nimi obchodzisz.', 'Przynieś 10 kwiatów trzęsawisk, 10 pradawnych porostów i 10 śniących chwał Morthisowi Szeptoskrzydłemu w Schronieniu Cenariona.', '', 'Wróć do Morthisa Szeptoskrzydłego na Moczarach Zangarskich.', '', '', '', '', 0),
(10979, 'plPL', 'Do Wiecznego Gaju', 'Na pewno $gwidziałeś:widziałaś; kruka w kurhanie?$B$BTo niepokojący obrót spraw. Niewiele możemy zrobić, żeby bezpośrednio pomóc Clintarowi i strażnikom snów, ale jeśli dowiemy się więcej o tym, co zagraża Szmaragdowemu Snowi, może zdołamy to powstrzymać.$B$BDowiadujemy się o odrodzeniu pradawnego kultu arakkoa w Górach Klingi – takiego, który czci kruczego boga. Idź do Wiecznego Gaju i odszukaj Arthorn Pieśń Wiatru. Może istnieje związek między tym, co dzieje się tam, a tym, co dzieje się w Szmaragdowym Śnie!', 'Porozmawiaj z Arthorn Pieśnią Wiatru w Wiecznym Gaju w Górach Klingi.', '', '', '', '', '', '', 0),
(10993, 'plPL', 'Powrót do Schronienia Cenariona', 'Zanieś esencje Morthisowi Szeptoskrzydłemu, razem z wieściami o tym, czego się dowiedzieliśmy o kruczym bogu.$B$BMorthis będzie wiedział najlepiej, jak użyć esencji i tych informacji, by wywabić Anzu z ukrycia. Śpiesz się do niego, bo nie wiadomo, jak długo Clintar i strażnicy snów zdołają się opierać natarciu kruka!$B$B<Arthorn chwyta cię za ramię, zanim zdążysz się odwrócić.>$B$BProszę, $N, powiedz Morthisowi, jak bardzo ci pomogłam. Obawiam się, że nie dostrzeże mojego udziału w tej pracy!', 'Zanieś Paczkę Arthorn Morthisowi Szeptoskrzydłemu w Schronieniu Cenariona.', '', '', '', '', '', '', 0),
(10994, 'plPL', 'W pogoni za kamieniem księżycowym', 'Jeśli połączy się esencje w rzadkim klejnocie, takim jak kamień księżycowy Południowej Furii, będziesz w stanie je uwolnić, gdy będziesz $ggotów:gotowa; rzucić wyzwanie Anzu.$B$BJedyny problem polega na tym, że kamienie księżycowe Południowej Furii występują tylko po stronie rzeki od Aszary, na urwiskach w pobliżu jej źródła.$B$BOstatnią wyprawę nocnych elfów, która szukała kamienia, spotkała tragedia. Ich łódź wciąż stoi na kotwicy na rzece, niedaleko miejsca, gdzie dostrzegli kamień księżycowy. Miej oczy szeroko otwarte i podejdź do tego miejsca lądem od strony Aszary.', 'Przynieś Kamień księżycowy Południowej Furii Morthisowi Szeptoskrzydłemu w Schronieniu Cenariona.', '', 'Wróć do Morthisa Szeptoskrzydłego na Moczarach Zangarskich.', '', '', '', '', 0),
(11001, 'plPL', 'Pokonaj kruczego boga', 'Nie możemy tracić czasu, musimy rozprawić się z kruczym bogiem. Musisz zanieść kamień księżycowy nasycony esencją do miejsca wielkiej mocy, by wywabić boga ze względnie bezpiecznego Szmaragdowego Snu.$B$BZejdź do Sal Sethekk i umieść kamień księżycowy w uścisku kruczego szponu. Znajdziesz go w komnacie przed salą Szponiego Króla.$B$BTrzeba sprawić, by Anzu uwierzył, że jego wyznawcy zebrali się, by powitać go z powrotem na świecie. Gdy się objawi, nie okazuj mu litości!', 'Zabij kruczego boga i wróć do Morthisa Szeptoskrzydłego w Schronieniu Cenariona.$B$BTo zadanie trzeba ukończyć na poziomie heroicznym.', '', 'Wróć do Morthisa Szeptoskrzydłego na Moczarach Zangarskich.', '', '', '', '', 0),
(11011, 'plPL', 'Wieczna czujność', 'Pokonanie Anzu, kruczego boga, to naprawdę niezwykłe osiągnięcie. Obawiam się jednak, że może nie porzucić dążenia do powrotu do Rubieży.$B$BDopóki ma tu wyznawców, będzie próbował powstać ponownie. Zatrzymaj kamień księżycowy nasycony esencją na wypadek, gdyby Anzu jeszcze dał o sobie znać.', 'Porozmawiaj z Morthisem Szeptoskrzydłym, by otrzymać Kamień księżycowy nasycony esencją.', '', '', '', '', '', '', 0),
(11531, 'plPL', 'Dziwna część silnika', 'Ta dziwna część silnika nie wygląda, jakby pasowała do pompy parowej, a co dopiero do czegokolwiek innego, co $gwidziałeś:widziałaś;. Może K. Lee Smallfry będzie coś o niej wiedzieć.', 'Zanieś Dziwną część silnika K. Lee Smallfry w Telredorze.', '', 'Wróć do K. Lee Smallfry w Telredorze na Moczarach Zangarskich.', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(9635, 'plPL', 'No i świetnie! Gdybyśmy jeszcze mieli rozciągliwą pętlę, zacisk do pergaminu, rurkę do siorbania i trochę lepkiej taśmy kaczej. Dopiero wtedy moglibyśmy coś porządnego zmajstrować!$B$BNo dobra, dobra, chyba na to $gzasłużyłeś:zasłużyłaś;, $N. Baw się dobrze!', 0),
(9636, 'plPL', 'Błyszczące! Zresztą który inżynier ma kiedykolwiek dość części zamiennych pod ręką? Och, może sprzedam nadwyżkę i kupię sobie trochę tych truskawkowych lodów Tigule\'a i Forora?! Uwielbiam truskawki! Myślisz, że gdzieś tu je mają?$B$BNo dobra, dobra, chyba na to $gzasłużyłeś:zasłużyłaś;, $N. Baw się dobrze!', 0),
(9697, 'plPL', 'Och, dobrze... nareszcie pomoc! Jest tyle do zrobienia, a ja muszę zostać tutaj, żeby wszystko zorganizować.$B$BMam nadzieję, że nie boisz się ubrudzić rąk.', 0),
(9701, 'plPL', 'Co?! Władcy trzęsawisk z Grani Quagg ZJADAJĄ strąki zarodniaków? To niedobrze!', 0),
(9702, 'plPL', 'To $gznalazłeś:znalazłaś;? Dziwne. Te łuskane resztki grzybów są niezwykłe, a zarazem jakoś znajome.$B$BMuszę się nad tym chwilę zastanowić. Nigdzie nie odchodź!', 0),
(9708, 'plPL', 'Zdecydowanie się zgadza. A obecność ogrów i to, co tam robiły, wszystko wyjaśnia. Teraz już rozumiem, czemu to się nazywa Wyrąbane Trzęsawisko, no jasne!$B$BMusimy coś z tym zrobić, tylko co? Nie możemy po prostu wybić wszystkich tych ogrów – mają takie samo prawo tu być jak wszystkie inne stworzenia na moczarach!', 0),
(9709, 'plPL', 'Są idealne! Och, dziękuję, $N!$B$B$GByłeś:Byłaś; tak $gostrożny:ostrożna;, żeby nie zaburzyć naturalnego porządku rzeczy, a zebraliśmy tyle informacji w tak krótkim czasie!$B$BA teraz zobaczmy, czy nasz mały plan wyhodowania nowego źródła pożywienia dla władców trzęsawisk się powiedzie.', 0),
(9714, 'plPL', 'Te się świetnie nadadzą, ale zawsze przyda się więcej. Może niedługo znów trafisz do Podbagna?', 0),
(9715, 'plPL', 'Te się świetnie nadadzą, ale zawsze przyda się więcej. Może niedługo znów trafisz do Podbagna?', 0),
(9716, 'plPL', 'To sprawka nag! Ale po co? Z tego, co opisujesz, ta pompa parowa musi być jedną z przyczyn spadku poziomu wody na moczarach!$B$BMniejsza z tym – to wyjaśnia ich otwartą wrogość wobec nas. Nie traćmy czasu, mam dla ciebie kolejne zadanie.', 0),
(9717, 'plPL', '<Zarodniak wydaje dźwięk, który przypomina nieco parsknięcie śmiechem.>$B$BŚwietnie! Nie ma wątpliwości, że morale zarodnikowych olbrzymów sięgnie dna, kiedy zorientują się, co $gzrobiłeś:zrobiłaś;.$B$BAlbo to, albo tak się rozwścieczą, że wkrótce znów nas zaatakują.$B$B<T\'shu robi ruch, jakby wzruszał ramionami.>', 0),
(9718, 'plPL', 'Tak, jak podejrzewałam. Nagi zbudowały stacje pomp przy wszystkich głównych jeziorach Moczarów Zangarskich.$B$BTrzeba je powstrzymać, jeśli moczary mają mieć jakąkolwiek przyszłość.', 0),
(9719, 'plPL', 'Czarny Tropiciel nie żyje! Zwykle nie cieszyłbym się z takiej rzezi, ale cierpienia, jakie wielka matka i jej potomstwo przez stulecia zadawały mojemu ludowi, są nie do opisania.$B$BSzkoda, że teraz kolejne z jej potomstwa przemieni się, by zająć jej miejsce, ale to potrwa, a my zyskamy trochę wytchnienia i przez jakiś czas nie będziemy musieli się martwić bagiennymi wędrowcami.', 0),
(9720, 'plPL', 'A więc stało się. Na razie moczary są ocalone.$B$BAle nie myśl ani przez chwilę, że to ostatnie, co słyszymy o nagach. Musimy mieć się na baczności przed wrogiem, kontynuując naszą misję w Rubieży.', 0),
(9726, 'plPL', '<Gzhun\'tt kiwa ci głową.>$B$BCieszymy się, że $gpotwierdziłeś:potwierdziłaś; naszą przyjaźń, $N. Może teraz, gdy mamy tak potężnego sojusznika, te nagi poganki dwa razy się zastanowią, zanim znów zaczną nas nękać?', 0),
(9727, 'plPL', '<Gzhun\'tt kiwa ci głową.>$B$BCieszymy się, że $gpotwierdziłeś:potwierdziłaś; naszą przyjaźń po raz kolejny, $N. Teraz, gdy już tyle razy $gdałeś:dałaś; im jasno do zrozumienia, o co nam chodzi, te bezsensowne ataki na nasz lud chyba wreszcie ustaną?', 0),
(9728, 'plPL', 'Dobra robota, $N. Lepiej wyzbądź się wszelkich wyrzutów sumienia, jeśli jakieś masz. Te nagi to okrutne stworzenia – jeszcze gorsze niż te z Azeroth.', 0),
(9729, 'plPL', 'Fhwoor to dobry olbrzym. Jakiś czas temu uratowaliśmy go przed nagami i od tamtej pory został tu i nam pomaga.$B$BMożemy tylko mieć nadzieję, że nagi zrozumieją aluzję: skoro zdołaliśmy przeniknąć do ich wioski i ukraść ich najcenniejszą własność, stać nas na znacznie więcej. Może teraz wrócą do swojego zbiornika i zostawią nas w spokoju?', 0),
(9730, 'plPL', 'Nie lubiłem nag w Azeroth, a tutaj lubię je jeszcze mniej. Wielka szkoda, że nasza misja nie mogła pozostać pokojowa, ale nie zobaczysz, żebym ronił łzy nad martwymi nagami.$B$BOto twoja nagroda za rozprawienie się z przywódcą Mrocznego Grzebienia, $N.', 0),
(9731, 'plPL', 'Nagi zamieniły Wężowe Jezioro w olbrzymi zlew dla wody z całych Moczarów Zangarskich. Co one mogą tam knuć?$B$BDobrze, że $gprzyniosłeś:przyniosłaś; nam te wieści, $N. Wyślemy oddział, by zbadał odkryty przez ciebie odpływ. Tymczasem mam dla ciebie inne zadanie.', 0),
(9738, 'plPL', 'Cieszę się, że niektórzy z moich przyjaciół jeszcze żyją, ale serce mi pęka, kiedy słyszę o losie pozostałych. <westchnienie>$B$BPrzynajmniej zginęli, robiąc to, co kochali najbardziej. Masz moją dozgonną wdzięczność za pomoc, $N.$B$BProszę, weź jedną z tych rzeczy w dowód wdzięczności.', 0),
(9739, 'plPL', 'Udało ci się! Mój lud ci dziękuje.$B$BMam nadzieję, że rozumiesz... to stąd biorą się nasze młode. Nie możemy pozwolić, żeby te bestie pożarły worki!', 0),
(9742, 'plPL', 'Tak! $GOcaliłeś:Ocaliłaś; kolejne worki zarodników.$B$BNie jesteś jak inni obcy. Opowiem mojemu ludowi o twoich czynach!$B$B<To zadanie można powtarzać aż do reputacji „Przyjazny”.>', 0),
(9743, 'plPL', '$GWróciłeś żywy:Wróciłaś żywa;! Opowiem o tobie innym zarodniakom! $N, $gpogromca:pogromczyni; olbrzymów!', 0),
(9744, 'plPL', 'Niewiarygodne! Trzeba by setek zarodniaków, żeby zabić tylu olbrzymów, ilu ty $gzabiłeś:zabiłaś;. Dopilnuję, żeby wszyscy dowiedzieli się o twoich wyczynach!$B$B<To zadanie można powtarzać aż do reputacji „Przyjazny”.>', 0),
(9747, 'plPL', 'Dziękuję, $N. Wreszcie będę mógł spokojnie spać w nocy. Gdybym nie był taki stary i słaby, sam rozprawiłbym się ze swoimi wrogami.$B$BWeź to złoto. To niewiele, ale twoja dobroć nie może zostać bez zapłaty.', 0),
(9752, 'plPL', '$GUratowałeś:Uratowałaś; jedną z moich druidek. Nigdy ci się nie odwdzięczymy, $N.$B$BDziękuję ci ja i dziękuje ci cała ekspedycja.', 0),
(9763, 'plPL', 'Nasz największy wróg w okolicy wreszcie nie żyje. $GWyświadczyłeś:Wyświadczyłaś; ekspedycji wielką przysługę, $N.$B$BNa zawsze pozostaniemy twoimi dłużnikami.', 0),
(9764, 'plPL', 'Vash!$B$BTo znacznie więcej, niż się spodziewaliśmy. Nasze drobne zwycięstwa nad nagami tu i ówdzie nic nie znaczą.$B$BJeśli w to zamieszana jest Lady Vash, działają tu siły znacznie potężniejsze od nas.$B$BDobrze, że $gprzyniosłeś:przyniosłaś; to do nas, $N. Teraz musimy przygotować się do wojny.', 0),
(9765, 'plPL', 'Doskonale się nadadzą, $N. Przynoś każde uzbrojenie, jakie znajdziesz. Potrzeby mamy wielkie, a zasoby skromne.', 0),
(9766, 'plPL', 'Świetna robota, $N. Nagi przekonają się, że nie warto nas lekceważyć.', 0),
(9769, 'plPL', 'Ładne sztuki, $N. Oto twoja zapłata.$B$B<Magasha wygina jedno ze skrzydeł i przykłada je sobie do głowy.>$B$BNie, to nie dla mnie, ale kim ja jestem, żeby narzekać?$B$B<Magasha wzrusza ramionami.>$B$BPieniądz mówi.', 0),
(9770, 'plPL', 'Już masz dość?$B$B<Reavij się śmieje.>$B$BNie bez powodu goście nie zostają tu długo.$B$BGdybym miał wybór, znalazłbym przyjemniejsze miejsce na posterunek, ale wolę już bagiennokły niż humory Denjaia.', 0),
(9771, 'plPL', 'Poturbowane zwłoki dokładnie pasują do opisu Zuraia. Cokolwiek zabiło zwiadowcę, najwyraźniej zaskoczyło go, bo jego broń tkwi w pochwie, a zawartość małego kałamarza poplamiła pobliską ziemię.', 0),
(9772, 'plPL', '<Zurai bierze od ciebie raport i przebiega go wzrokiem.>$B$BWiększość z tego już wiemy. Wszystko w okolicy wydaje się wyschnięte albo zwiędłe, ale tu jest coś nowego.$B$BPisze, że grzybowe olbrzymy chyba oszalały z braku wilgoci. Z twojego opisu wynika, że to właśnie one go zabiły.$B$BKażę moim ludziom omijać tę okolicę. Nie stać nas na kolejne straty.', 0),
(9773, 'plPL', 'Nareszcie odmiana po tych nudnych grzybach! Gdybyś nie $gcuchnął:cuchnęła; rybą, uściskałabym cię.$B$BZobaczymy, jak inni będą zazdrościć, kiedy poczują mięso pieczone nad ogniem.', 0),
(9774, 'plPL', 'Dziękuję, $N. Każdy kawałek się przyda.$B$BJeszcze długa droga przede mną, ale spójrzmy prawdzie w oczy: co innego mam robić między patrolami?', 0),
(9775, 'plPL', 'Czemu nie mówisz od razu, że masz raport od Zuraia? Czekam na wieści od niego.$B$BWysłałem go tam, żeby zaznaczył naszą obecność na wschodniej granicy, a nie siedział z założonymi rękami. Zobaczmy, co ma do powiedzenia.', 0),
(9776, 'plPL', 'Jeśli Anachoreta Ahuurn uważa cię za przyjaciela, może okażesz się $ggodny:godna; zaufania. Wybacz mi moją ostrożność, ale często tylko ona dzieli mój lud od śmierci. Możesz znaleźć u nas schronienie, a może z czasem nasze wzajemne zaufanie wzrośnie.', 0),
(9777, 'plPL', 'To dobre zarodniki, powinny nam wystarczyć na dość długo. Dziękuję, że $gpomogłeś:pomogłaś; nam uzupełnić zapasy, $N.', 0),
(9778, 'plPL', 'Przysłała cię Ysiel? Jasne, że przyda mi się ktoś taki jak ty! Zawsze brakuje nam trochę siły.', 0),
(9780, 'plPL', 'Dziękuję za pomoc, $N. Twoja hojność nie zostanie zapomniana.', 0),
(9781, 'plPL', 'Dobra robota. To powinno w najbliższym czasie zmniejszyć zapotrzebowanie na żywność w okolicy, choć i tak będziemy musieli znaleźć nowe jej źródła. Ryby i grzyby wystarczają, ale różnorodności nigdy nie należy lekceważyć.', 0),
(9782, 'plPL', 'Hmm... Gleba wydaje się wyjałowiona, więc wbrew temu, co myślałem, nie ona jest przyczyną problemu. Co łączy to wszystko? Dlaczego wszystko nagle umiera?', 0),
(9783, 'plPL', 'Dziękuję za pomoc w tym trudnym zadaniu, $N. Nasza praca na Martwym Grzęzawisku jeszcze się nie skończyła, ale teraz skupimy się na tym, by w miarę możliwości przywrócić tam równowagę.', 0),
(9784, 'plPL', 'Doskonale. Przynoś mi więcej części roślin, jeśli jakieś znajdziesz.$B$B<To zadanie można powtarzać aż do reputacji „Szanowany”.>', 0),
(9785, 'plPL', '$GWróciłeś:Wróciłaś;. $GOtrzymałeś:Otrzymałaś; błogosławieństwa pradrzew?', 0),
(9786, 'plPL', 'A więc ruiny zajęli Zagubieni z Dzikich Mokradeł? Bardzo ciekawe. Musieli zachować jakąś pamięć o swoim dziedzictwie i znaczeniu tego miejsca. Musimy dowiedzieć się więcej, $N. Ta świątynia może być kluczem do odkupienia Zagubionych i ponownego połączenia wielu rozproszonych gałęzi draenei.', 0),
(9787, 'plPL', 'To w zupełności wystarczy, $N. Wygląda na to, że mają obsesję na punkcie ptaków, co jest dziwne, bo na Moczarach Zangarskich nie żyją żadne rodzime gatunki ptaków. Co to może znaczyć?$B$BCzyżby zetknęli się z arakkoa? Dla ludu wyznającego szamanizm mogą się one wydawać wcieleniem potężnego ptasiego ducha.', 0),
(9788, 'plPL', 'Moje rzeczy! Wszystkie są tutaj!$B$BDziękuję ci, $N. Tak jak obiecałem, pozwolę ci wybrać dla siebie jeden z przedmiotów. Nie mam wiele do zaoferowania, ale mój lud zawsze dzielił się tym niewiele, co ma.', 0),
(9790, 'plPL', 'Dziękuję, $N.$B$B<Haalrun uśmiecha się ze współczuciem.>$B$BPrzynajmniej nie musisz ich czyścić. To najgorsza robota ze wszystkich, ale kiedy już się ją zrobi, nikt by nie zgadł, że były przyczepione do olbrzymiego owada.', 0),
(9791, 'plPL', 'Dziękuję za pomoc w przetrzebieniu bagiennokłych rozpruwaczy, $N. Gdyby miały choć trochę rozumu, może nauczyłyby się, że najlepiej żyć i dać żyć innym.$B$B<Noraani wzrusza ramionami.>$B$BOlbrzymie, przerośnięte robale z rozumem. Ciekawe, jak by to wyglądało...', 0),
(9792, 'plPL', 'Ikuti jest dla mnie jak brat. Jego przyjaciel jest moim przyjacielem. Jesteś tu mile $gwidziany:widziana;, $N, i dziękujemy ci za pomoc naszemu ludowi.', 0),
(9793, 'plPL', 'Hmm... Pamiętam, jak nasi zwiadowcy mówili o ruinach draenejskiej osady w północnej części puszczy. Sam niewiele o nich wiem, ale możesz porozmawiać z którymś ze zwiadowców.', 0),
(9794, 'plPL', 'A więc $gprzyniosłeś:przyniosłaś; odpowiedź Timothy\'ego?$B$B<Kialon przerywa na chwilę, by przeczytać list, po czym się śmieje.>$B$BWszystko ma pod kontrolą, powiada. Nie potrzebuje pomocy, powiada. Mogłem to przewidzieć!$B$BNiektórzy nigdy się nie zmieniają. Patrz, nawet znalazł czas, żeby poprawić mi ortografię.$B$B<Kialon wzdycha bez przekonania.>$B$BNie powinienem był wysyłać tego listu. Zapomniałem się. Specjalista zawsze ma sytuację pod kontrolą. Zawsze.', 0),
(9795, 'plPL', 'Denjai prosi o pomoc? Wysłałbym mu posiłki, ale i tak jesteśmy tu rozproszeni. Mamy tu na górze własne kłopoty z ogrami.$B$BKiedy tylko będę mógł, przekażę mu, co wiemy o tutejszych plemionach ogrów i ich taktyce. Może jeśli wytrzyma wystarczająco długo, zdołamy uderzyć na tę plugawą hołotę z dwóch stron.', 0),
(9796, 'plPL', 'Najwyższy czas, żeby postawił tę placówkę na nogi. Straciliśmy o wiele za dużo gońców przez zwiadowców Przymierza.', 0),
(9797, 'plPL', '<Choć stara się to ukryć, na twarzy Kroghana maluje się ulga.>$B$BNajwyższy czas, że tu $gdotarłeś:dotarłaś;! Co prawda nie jesteś armią, ale każdy, kto jest zdolny do walki i potrafi władać bronią albo rzucić zaklęcie, jest tu mile widziany. Mieszkańcy Garadaru są krewnymi całej Hordy i z dumą przelewamy krew w ich obronie.', 0),
(9801, 'plPL', 'To się świetnie nada. Daj mi chwilę na przygotowanie mikstury.', 0),
(9802, 'plPL', 'Spadek liczebności rodzimych gatunków z pewnością budzi niepokój. Wzrost liczby gatunków inwazyjnych może mieć związek z niedawnym zaburzeniem ekosystemu. Nie mam jeszcze dość informacji, żeby wyciągnąć wnioski.$B$B<Lauranna, przeglądając części roślin, zapisuje kilka uwag w dzienniku.>$B$BWeź to, $N. Może ci się przydać.$B$BPrzynoś mi wszystkie inne części roślin, jakie znajdziesz. Uwzględnię je w moich statystykach.', 0),
(9803, 'plPL', 'Odmówili? Oczywiście mają prawo wybrać własną drogę, ale ich wybór mnie zaskakuje. Sądziłem, że wszyscy draenei, także Złamani i Zagubieni, wciąż pamiętają, że jesteśmy jednym ludem.$B$BPewnie ma rację, że oszukiwanie ich było niemądre, ale czyż nie widział, że mieliśmy przyjazne zamiary?', 0),
(9806, 'plPL', 'To wspaniałe zarodniki, $N! Wysokołodygi są niezbędne do odbudowy naszego miasta. A po wszystkich atakach władców trzęsawisk bardzo nam ich brakuje.', 0),
(9807, 'plPL', 'Doceniamy twoją pomoc, $N. Nie przestaniesz, prawda?', 0),
(9808, 'plPL', 'To pomoże nam handlować z innymi zarodniakami i zdobywać żywność i zapasy. Sporeggar ci dziękuje, $N!', 0),
(9809, 'plPL', 'Dziękuję, $N. Jako starszy Sporeggaru muszę dbać, by mój lud miał dość zapasów. Bardzo ułatwiasz mi to zadanie.', 0),
(9814, 'plPL', 'Te są wspaniałe, mon!$B$BWiesz co? Skoro $gbyłeś:byłaś; w porządku i $gpomogłeś:pomogłaś; z grzybami, dopuszczę cię do zabawy!', 0),
(9816, 'plPL', 'Świetna robota, mon! Mam nadzieję, że dobrze się bawili!', 0),
(9817, 'plPL', 'Założę się, że Krwawa Łuska dwa razy się zastanowi, zanim znów zaatakuje zwiadowców ekspedycji. Weź to w nagrodę, $N. $GZasłużyłeś:Zasłużyłaś;.', 0),
(9820, 'plPL', 'Dobra robota, $N. Ale obecność tych ogrów tak blisko naszej placówki naprawdę mnie niepokoi. Wygląda na to, że od jakiegoś czasu przesączają się tu z gór na północy.', 0),
(9822, 'plPL', '<Łowca cieni Denjai przygląda się planom.>$B$BWiedziałem! Smród ogrów zawsze niesie ze sobą ukrytą groźbę. Teraz, gdy mamy dowód ich zamiarów, musimy uderzyć pierwsi.', 0),
(9823, 'plPL', 'Twoje zwycięstwo nad Ango\'rosh trzeba uczcić, $N. Ciekawe, ile czasu minie, zanim te ogrze osiłki znajdą sobie kolejnego żądnego krwi wodza.$B$BMniejsza z tym, będziemy na nich gotowi.', 0),
(9827, 'plPL', 'Wygląda na podstawkę trzęsawiskowego olbrzyma, ale nigdy nie widziałem takiej w tym stanie. Słyszałem, że olbrzymy na Martwym Grzęzawisku zaczęły usychać, ale to zaszło znacznie dalej, niż się spodziewałem.$B$BMartwe Grzęzawisko było kiedyś jeziorem, jak inne na moczarach, i służyło olbrzymom za miejsce rozrodu. Woda opada, a te zmiany najwyraźniej nie pozwalają olbrzymom wytwarzać zarodników. Jeśli tak dalej pójdzie, olbrzymy mogą całkiem zniknąć.', 0),
(9828, 'plPL', 'Wygląda na podstawkę władcy trzęsawisk, ale nigdy nie widziałem takiej w tym stanie. Słyszałem, że olbrzymy na Martwym Grzęzawisku zaczęły usychać, ale to zaszło znacznie dalej, niż się spodziewałem.$B$BMartwe Grzęzawisko było kiedyś jeziorem, jak inne na moczarach, i służyło olbrzymom za miejsce rozrodu. Woda opada, a te zmiany najwyraźniej nie pozwalają olbrzymom wytwarzać zarodników. Jeśli tak dalej pójdzie, olbrzymy mogą całkiem zniknąć.', 0),
(9830, 'plPL', 'Dziękuję, że $gprzyniosłeś:przyniosłaś; ten jad, $N. Dzięki niemu będę mógł przeprowadzić pokaz, nie uszczuplając własnych zapasów.', 0),
(9833, 'plPL', 'To wspaniałe wieści. Droga wciąż jest daleka od pełnego bezpieczeństwa, ale posłańcy są sprytni i zaradni.', 0),
(9834, 'plPL', 'To dobre skóry, Maktu tak myśli. Będą z nich bardzo dobre zbroje.$B$BKto wie? Może nawet zostanie dość, żeby Maktu zrobił trochę zbroi dla draenei.', 0),
(9835, 'plPL', 'Na razie zagrożenie ze strony Ango\'rosh jest opanowane, ale jestem pewien, że tak łatwo się nie poddadzą. Od końca mojego życia jako draeneja zapomniałem wiele rzeczy, ale upór ogrów to wspomnienie, które trwa.', 0),
(9839, 'plPL', 'Nareszcie! Dziękujemy ci za pomoc w umocnieniu naszej pozycji w Przystani Orebor. Wyślę wieść o twoich czynach do Telaar, miasta Kurenai w Nagrandzie. Nasze ludy będą miały jeszcze wiele okazji do współpracy.', 0),
(9841, 'plPL', 'Tak myślałem. Już słyszę różnicę. Dzięki tobie wreszcie będę mógł wrócić do pracy. Jeśli kiedyś będziesz potrzebować materiałów rzemieślniczych, nie zapomnij o starym Gambarince!', 0),
(9842, 'plPL', 'Te powinny mi wystarczyć na dłuższy czas! Chyba inni zaczęli to zauważać. Dostałem już kilka ofert kupna moich ostrzy. Sprzedawanie ich na boku może się okazać lepszym interesem niż moje zwykłe towary.', 0),
(9845, 'plPL', 'Nie mogę się doczekać powrotu do wędkowania! Teraz wrócę do miasta z prawdziwymi rybami w wiadrze i Gambarinka nie będzie się już mógł ze mnie naśmiewać!', 0),
(9846, 'plPL', 'Hmm... Wydaje się, że dzielą się na wizerunki wężowego ducha i ptasiego ducha. Żaden szanujący się troll z Mrocznej Włóczni nie oddaje czci ptakom. Ich duchy są słabe i kapryśne, lepiej zostawić je Amanom.$B$BAle wąż, $N, wąż ma znaczną moc i to tego ducha będę badać.', 0),
(9847, 'plPL', '<Opowiadasz Jasnowidzce Janidi, co się stało, gdy $gużyłeś:użyłaś; totemu.>$B$BDuch cię zaatakował? Musi być silniej związany z tymi Zagubionymi, niż myślałam. Nie da się go zmusić do służby bez ogromnego wysiłku. Będę musiała poszukać nowego źródła mocy w tym nędznym świecie.', 0),
(9848, 'plPL', '<Timothy kartkuje podręcznik.>$B$BUżywają postrzępionego welonu jako podstawy trucizny? Nie, to nie może być prawda. Postrzępiony welon nie ma żadnych właściwości toksycznych.$B$BDodawanie postrzępionego welonu do trucizny to jak łotrzyk walczący dwoma buzdyganami. Jasne, da się, ale to sprzeczne z istotą twojego powołania! Po prostu nie pojmuję...$B$B<Timothy odchrząkuje.>$B$BTo znaczy, dziękuję, że mi to $gprzyniosłeś:przyniosłaś;. Wypróbuję truciznę, jak tylko znajdę czas.', 0),
(9875, 'plPL', 'Nowy gatunek! Na pewno?$B$B<Lauranna przerzuca strony notatek i szkiców.>$B$BDobra robota, $N. Musimy dopisać go do naszej listy. Co powiesz na „$Nium fioletowolistne”? Brzmi całkiem nieźle.', 0),
(9876, 'plPL', 'Dzięki Cenariusowi, że się $gzjawiłeś:zjawiłaś;. Przez moje rany nie mogłam wyjść na zewnątrz po pomoc.', 0),
(9894, 'plPL', 'Masz moją wdzięczność, $N, i wdzięczność wartowników. Ucieszą się, słysząc, że mogą kontynuować pracę na południu bez obawy przed atakiem.', 0),
(9895, 'plPL', 'Teraz, gdy na własne oczy $gzobaczyłeś:zobaczyłaś; objawy zachwianej równowagi, zwracaj na nie uwagę w swoich wędrówkach.', 0),
(9896, 'plPL', 'Nie wiem, jak ci dziękować, $gchłopcze:dziewczyno;. Ale będę miał uciechę...', 0),
(9898, 'plPL', 'Fantastycznie! Nigdy nie zapomnę, jak $gpomogłeś:pomogłaś; mi zdobyć jej serce. Właściwie możesz być honorowym gościem na naszym weselu.', 0),
(9899, 'plPL', 'Przynajmniej ktoś tu wykonuje swoją część roboty. Dziękuję, że $gzająłeś:zajęłaś; się tą sprawą, $N. Muszę porozmawiać z Zuraiem o Reaviju. Dość już tych jego intryg i bujania w obłokach.', 0),
(9901, 'plPL', 'Dobra robota, $N. Chyba ty i ja przyćmiliśmy cały zespół poszukiwaczy. Kiedy wrócę do Żelaznej Kuźni, na pewno pozwolą mi wybrać sobie przydział.', 0),
(9902, 'plPL', 'Dziękuję, $N. Może z pomocą draenei te moczary pewnego dnia uwolnią się od nag. Nie potrafię sobie wyobrazić, jak to jest być zmuszonym do służby u nich.$B$BNie mówi o tym często, ale Maktu był kiedyś niewolnikiem.', 0),
(9903, 'plPL', 'Staruszek na pewno czuł, że jego dni dobiegają końca. Przy tych wszystkich przybyszach dawny porządek nie mógł się utrzymać. Może to i lepiej, że jego duch zaznał teraz spokoju.', 0),
(9904, 'plPL', 'Nareszcie! Mówią, że każdy wielki rybak ma swoją opowieść o „tej, co uciekła”, ale ja jeszcze nie spotkałam stworzenia, którego nie pokonałabym w ten czy inny sposób.', 0),
(9905, 'plPL', '<Maktu kiwa głową z uznaniem.>$B$BMaktu jest wdzięczny za twoją pomoc. Duma Maktu jest zaspokojona. Już nikt go nie zaskoczy.', 0),
(9911, 'plPL', 'Na pewno jest prawdziwa? To znaczy, wiedziałam, że na moczarach żyją duże zwierzęta, ale są olbrzymie stworzenia, a są OLBRZYMIE robale.$B$BTeraz sobie przypominam, że zarodniaki opowiadały o groźnej płaszczce Otchłani, która terroryzowała je, zanim wtargnęli władcy trzęsawisk.$B$BA jeśli te opowieści są prawdziwe? O rety. Lepiej wezmę to na przechowanie. Ekspedycja będzie chciała się o tym dowiedzieć.', 0),
(9919, 'plPL', '$GPomogłeś:Pomogłaś; ochronić następne pokolenie zarodniaków. Możemy ci się odwdzięczyć tylko w jeden sposób: przyjmując cię w naszych domach. Zostań na chwilę i poznaj inne zarodniaki. Będą miały mnóstwo pytań, mam nadzieję, że nie masz nic przeciwko.', 0),
(9957, 'plPL', 'Cieszę się, że schronienie cię przysłało. Druidzi z gąszczu zostali zabici! Przeżyłem tylko ja i jeszcze jeden, który postradał zmysły.$B$BNie wiem, co się stało, ale zamierzam to wyjaśnić. Cokolwiek to było, stało się szybko i wydaje się nienaturalne.$B$BPomożesz mi?', 0),
(10096, 'plPL', 'Dobrze! Te bagienne bestie nie mają prawa najeżdżać domu sporeloków!$B$BByłoby lepiej, gdyby te stworzenia nauczyły się żyć w zgodzie, ale jeśli to niemożliwe, będziemy tu, żeby zaradzić sytuacji!$B$BProszę, weź jedną z tych rzeczy w podziękowaniu za pomoc.', 0),
(10104, 'plPL', 'Pochlebia mi, że twój złamany przyjaciel uważa mnie za znawcę relikwii jego ludu, ale szczerze mówiąc, odkąd tu przybyłem, nie miałem zbyt wielu okazji, żeby je badać. Z pewnością taki miałem zamiar, ale po przybyciu okazało się, że inne sprawy wymagają mojej uwagi.', 0),
(10105, 'plPL', 'Miałam nadzieję, że jego ludzie szybciej ukończą placówkę, ale to nie jego pieniądze idą w błoto. Cóż, zawsze to postęp.', 0),
(10115, 'plPL', 'Dobrze się $gspisałeś:spisałaś;, $N. Plemię Sztyletowych Mokradeł jest poza wszelkim odkupieniem, pod każdym względem, ale nie jestem pewien, czy draenei działaliby w tej sytuacji dość szybko.', 0),
(10116, 'plPL', 'Niezwykłe! Inni też próbowali zdobyć tę nagrodę, ale nigdy nie wrócili. Nietrudno zgadnąć, co się z nimi stało.$B$BUlżyło mi, że Mummaki i jego zwyrodnialcy nie będą nas już nękać.', 0),
(10117, 'plPL', 'Dziękuję ci, $N. Zaczynałem już myśleć, że będę musiał sam wyruszyć tam ze sporą częścią garnizonu i rozprawić się z Mummakim. A wtedy nie wiadomo, co by się stało z Zabra\'jin.', 0),
(10118, 'plPL', 'Chyba udało ci się przekazać im dość dobitną wiadomość. Może teraz reszta moich ludzi nie będzie się tak bała ruszyć do walki ze Sztyletowymi Mokradłami. A jeśli będzie, to niech się wstydzi swojego tchórzostwa.', 0),
(10355, 'plPL', '<Ruam z zatroskaną miną bada próbki.>$B$BJest dokładnie tak, jak się obawiałem, $N. Wysychające środowisko ciężko doświadcza stworzenia, które nigdy nie miały żyć poza bagnami. Będziemy musieli dalej obserwować tę okolicę i naradzić się z Ekspedycją Cenariońską, czy da się coś zrobić.', 0),
(10897, 'plPL', 'Świetnie! Widzę, że palisz się do nauki, więc bierzmy się do dzieła. Nauczę cię, jak najlepiej wykorzystać rośliny, których używasz w miksturach alchemicznych.$B$BPrzekonasz się, że zioła mogą wystarczyć na naprawdę długo, jeśli wiesz, co robisz. Czasem z materiałów, które z początku $guznałbyś:uznałabyś; za potrzebne do jednej mikstury, zrobisz dwie.', 0),
(10945, 'plPL', 'Dziękuję za tę okazję, by znów zobaczyć Salandrię. Przez ten rok bardzo za nią tęskniłam, ale wciąż jesteśmy dobrymi przyjaciółkami.$b$bUmówiłyśmy się, że kiedy dorośniemy, obie zostaniemy dzielnymi poszukiwaczkami przygód, tak jak ty!', 0),
(10961, 'plPL', '$GPrzyniosłeś:Przyniosłaś; składniki na napar? Tylko proszę, uważaj, żeby nie obsypać mnie pyłkiem. Przy nim kicham bez opamiętania.$B$B<Morthis pociąga nosem, urażony na samą myśl o upokarzającym kichnięciu.>$B$B<Morthis bierze od ciebie zioła i je ogląda. Wyjmuje fiolkę i zaczyna mieszać miksturę.>$B$BTo potrwa tylko chwilę, $N. Potem musisz udać się do Gaju Luny.', 0),
(10979, 'plPL', '<Arthorn słucha, jak wyjaśniasz, że Morthis Szeptoskrzydły przysłał cię, byś $gzbadał:zbadała; związek między kultem kruczego boga a dziwnymi wydarzeniami w Gaju Luny. Choć wiadomość ją wstrząsa, wydaje się bardziej rozczarowana jej charakterem.>$B$BO rety...$B$BPomagam Timeonowi w jego badaniach nad kultem kruka, ale nigdy nie przypuszczaliśmy, że jego patron sięga poza Góry Klingi!', 0),
(10993, 'plPL', '<Morthis bierze paczkę, otwiera ją, znajduje notatki Arthorn i czyta je, nie komentując autorki.>$B$BZ jednej strony ulżyło mi, że wreszcie znamy tożsamość wroga, ale ten Anzu to istota o znacznej mocy. Znajomość natury i imienia przeciwnika jest niezbędna, ale nie jesteśmy jeszcze gotowi stawić mu czoła.', 0),
(10994, 'plPL', '<Morthis wydaje się rozdarty: z jednej strony chciałby się roześmiać z twojej opowieści, z drugiej pamięta, jak niewiele brakowało, żeby kamień przepadł. W końcu tylko wpatruje się w świecący kamień.>$B$BZabiorę się do nasycania go esencjami ptasich duchów. Wkrótce będziesz $ggotów:gotowa; rzucić wyzwanie naszemu wrogowi.', 0),
(11001, 'plPL', 'Dobrze cię znowu widzieć, $N. Twój triumf nad kruczym bogiem znaczy o wiele więcej niż jakakolwiek próba czy rytuał przejścia, jaki mógłbym ci wyznaczyć.$B$BNaprawdę $gudowodniłeś:udowodniłaś;, że $gjesteś godny:jesteś godna; wiedzy, której Druidzi Szponu strzegą od niezliczonych pokoleń.', 0),
(11011, 'plPL', 'Zatrzymaj kamień księżycowy przy sobie, $N. Jeśli podejrzewasz, że Anzu zbiera siły, by znów spróbować powrócić do tego świata, użyj go, by ponownie go pokonać.', 0),
(11531, 'plPL', '<K. Lee przygląda się części silnika, a potem przez chwilę patrzy gdzieś w dal.>$B$BTo coś naprawdę wyjątkowego. Trudno powiedzieć, skąd pochodzi – jakby po prostu spadło z nieba. Zatrzymam to i zapłacę ci za fatygę.$B$BAle tak między nami, chyba lepiej nikomu o tym nie wspominać.$B$B<K. Lee przywołuje na twarz swój najbardziej czarujący uśmiech.>', 0),
(11758, 'plPL', 'Zbezcześć wielkie ognisko Przymierza na Moczarach Zangarskich!', 0),
(11787, 'plPL', 'Zbezcześć wielkie ognisko Hordy na Moczarach Zangarskich!', 0),
(11829, 'plPL', 'Uczcij płomień Moczarów Zangarskich!', 0),
(11863, 'plPL', 'Uczcij płomień Moczarów Zangarskich!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(9635, 'plPL', 'Masz już te części? Mam tu trochę nurkowania do zrobienia.', 0),
(9636, 'plPL', 'Masz już te części? Muszę naprawić cewkę sprężającą, zanim Anachoreta Ahuurn zacznie mi stać nad głową!', 0),
(9701, 'plPL', 'Już z powrotem? Twoja obserwacja zarodniaków ze Sporeggaru ma kluczowe znaczenie dla moich badań. Mam nadzieję, że nie należysz do tych, którzy wszystko robią w pośpiechu. Wykaż się cierpliwością i upewnij się, że $gzbadałeś:zbadałaś; cały Jar Wylęgu, zanim złożysz mi ostateczny raport.', 0),
(9702, 'plPL', 'Pamiętaj, żeby starannie zebrać wszystkie dowody, $N! Składamy tu w całość olbrzymią układankę. Twój błąd mógłby nas doprowadzić do fałszywych wniosków.$B$BI gdzie wtedy byłoby nasze rozumienie ekologii Moczarów Zangarskich?', 0),
(9708, 'plPL', 'Masz już te próbki?', 0),
(9709, 'plPL', 'Masz wszystkie grzyby potrzebne do założenia nowego ogrodu dla władców trzęsawisk?', 0),
(9714, 'plPL', 'Wciąż przyda nam się więcej krwistego hibiskusa od łazęgów, trzęsawiskowych olbrzymów i podbagiennych nietoperzy z Podbagna w Zbiorniku Żmijokolców. Przynoś mi je po pięć, a będę ci bardzo wdzięczny.', 0),
(9715, 'plPL', 'Masz już cały hibiskus, o który cię prosiłem?', 0),
(9716, 'plPL', '$GOdkryłeś:Odkryłaś; coś, $N?', 0),
(9717, 'plPL', 'Podbagno to bardzo niebezpieczne miejsce. Nie uznałbym cię za tchórza, gdybyś się $gwzdragał:wzdragała; przed wyprawą tam. Ale też nie byłbym ci wdzięczny, gdybyś nie $gwrócił:wróciła; z tym, o co prosiłem.', 0),
(9719, 'plPL', '$GWróciłeś:Wróciłaś;. Czy to znaczy, że Czarnego Tropiciela już nie ma?', 0),
(9720, 'plPL', 'Czy to już zrobione, $N?', 0),
(9726, 'plPL', '$GZłożyłeś:Złożyłaś; już wizytę nagom?', 0),
(9727, 'plPL', '$GZłożyłeś:Złożyłaś; już wizytę nagom?', 0),
(9728, 'plPL', 'Dobrze cię znowu widzieć, $N. Jak idą łowy na nagi?', 0),
(9729, 'plPL', 'Czy z Fhwoorem wszystko w porządku? $GOdzyskałeś:Odzyskałaś; arkę?', 0),
(9730, 'plPL', 'Chcesz porozmawiać o nagrodzie za Haghazeda? No więc, nie żyje? Poza tym nie ma o czym mówić!', 0),
(9738, 'plPL', '$GOdkryłeś:Odkryłaś; już, gdzie się podziewa moja czwórka towarzyszy?', 0),
(9739, 'plPL', 'Worki zarodników! $GZdobyłeś:Zdobyłaś; je?', 0),
(9742, 'plPL', '$GOcaliłeś:Ocaliłaś; jeszcze jakieś worki zarodników?', 0),
(9743, 'plPL', 'Jak idzie zabijanie władców trzęsawisk? Naucz te bydlaki, żeby nie wchodziły na ziemie zarodniaków!', 0),
(9744, 'plPL', '$GZabiłeś:Zabiłaś; wiele olbrzymów, ale zostało ich jeszcze mnóstwo. I wciąż atakują nasze worki zarodników!', 0),
(9747, 'plPL', '$GWróciłeś:Wróciłaś;. Czy Kataru i łowcy niewolników z Cienistych Mokradeł nie żyją?', 0),
(9763, 'plPL', 'Co z Kalithreshem? Już nie żyje, $N?', 0),
(9764, 'plPL', 'Co tam masz, $N?', 0),
(9765, 'plPL', '$GZdobyłeś:Zdobyłaś; uzbrojenie, którego szukam, $N?', 0),
(9766, 'plPL', 'Przekujemy stal samych nag na broń, której użyjemy przeciwko nim. Przynieś mi całe uzbrojenie, jakie zdołasz wynieść ze Zbiornika Żmijokolców.', 0),
(9769, 'plPL', 'A to co? Ukąsił cię skrzydlaty robal, co?$B$B<Magasha chichocze z własnego żartu.>', 0),
(9770, 'plPL', 'Wciąż widzę bagiennokły, $N. Chyba nie $gskończyłeś:skończyłaś; tak szybko.', 0),
(9772, 'plPL', '$GWróciłeś:Wróciłaś;, ale Jyoby z tobą nie ma. Co się z nim stało?', 0),
(9773, 'plPL', 'Powiedz, że nie $gwróciłeś:wróciłaś; z pustymi rękami, $N.', 0),
(9774, 'plPL', 'Widzę ten twój uśmieszek. Tak, moja zbroja będzie wyglądać trochę dziwnie, dopóki nie wymienię całego starego metalu, ale lepsze to niż brak ochrony.', 0),
(9775, 'plPL', 'Nie wyglądasz na jednego z moich ludzi. Mów, z czym przychodzisz.', 0),
(9777, 'plPL', 'Wygląda na to, że niedługo będziemy musieli uzupełnić zapas zarodników.', 0),
(9780, 'plPL', 'Masz jakieś ryby do naszych zapasów?', 0),
(9781, 'plPL', 'Jak idą łowy, przyjacielu?', 0),
(9782, 'plPL', '$GZdobyłeś:Zdobyłaś; próbkę gleby z Martwego Grzęzawiska?', 0),
(9783, 'plPL', 'Zabijanie stworzeń z Martwego Grzęzawiska sprawia mi ból, ale nie da się ich już ocalić. Najlepsze, co możemy zrobić, to odnowić tę okolicę i wychować nowe pokolenie.', 0),
(9784, 'plPL', 'Wciąż przydałoby mi się więcej części roślin. Skoro jeziora tracą wodę, mam wrażenie, że przybywa gatunków inwazyjnych. Potrzebuję jednak więcej danych, by poprzeć moją teorię.', 0),
(9785, 'plPL', '$GRozmawiałeś:Rozmawiałaś; już z pradrzewami, $N?', 0),
(9786, 'plPL', '$GZbadałeś:Zbadałaś; Ruiny Boha\'mu? Wyobrażasz sobie, jak wyglądały w pełni swojej świetności?', 0),
(9787, 'plPL', 'Masz idole?', 0),
(9788, 'plPL', '$GZnalazłeś:Znalazłaś; moje rzeczy, $N? Jaskinia jest niedaleko Cienistych Mokradeł, blisko granicy z Nagrandem.', 0),
(9790, 'plPL', 'Udało ci się zebrać jakieś przejrzyste skrzydła?', 0),
(9791, 'plPL', 'Jak ci idą łowy na bagiennokły?', 0),
(9793, 'plPL', 'W czym mogę pomóc?', 0),
(9794, 'plPL', '<Kialon przygląda ci się podejrzliwie.>$B$BNie znam cię. Masz do mnie jakąś sprawę?', 0),
(9801, 'plPL', '$GZebrałeś:Zebrałaś; składniki?', 0),
(9802, 'plPL', '$GZnalazłeś:Znalazłaś; jakieś części roślin, $N?', 0),
(9803, 'plPL', '$GRozmawiałeś:Rozmawiałaś; ze starszym plemienia Dzikich Mokradeł?', 0),
(9806, 'plPL', '$GWróciłeś:Wróciłaś;, $N. $GZdobyłeś:Zdobyłaś; żyzne zarodniki?', 0),
(9807, 'plPL', 'Żyzne zarodniki zawsze się przydadzą. Wysokołodygi to niezwykle przydatne grzyby. Dzięki temu, że możemy je hodować, mamy z nich wiele pożytku.', 0),
(9808, 'plPL', '$GZnalazłeś:Znalazłaś; jakieś świecące kapelusze, $N? Są dosłownie wszędzie na moczarach.$B$BJeśli się przyjrzysz, z daleka dostrzeżesz ich jasną poświatę.', 0),
(9809, 'plPL', 'Chętnie wezmę więcej świecących kapeluszy, jeśli je masz. Naszej wiosce zawsze się przydadzą.', 0),
(9814, 'plPL', 'Masz grzyby, mon?', 0),
(9816, 'plPL', '<Znachor Tor\'gash szczerzy zęby.>$B$BI jak, małym Zagubionym spodobał się prezent?', 0),
(9817, 'plPL', 'Przychodzisz po nagrodę za Fyashe? To najlepsza wiadomość, jaką dziś usłyszałem.', 0),
(9820, 'plPL', 'Co tam masz, $N?', 0),
(9822, 'plPL', '$GZnalazłeś:Znalazłaś; dowód zamiarów ogrów?', 0),
(9823, 'plPL', 'Nad nami wisi groźba ze strony Ango\'rosh. $GZlikwidowałeś:Zlikwidowałaś; ich przywódcę?', 0),
(9827, 'plPL', 'Co tam masz, $N?', 0),
(9828, 'plPL', 'Co tam masz, $N?', 0),
(9830, 'plPL', 'Chcę pokazać Anachorecie Ahuurnowi i innym w Telredorze, do czego może służyć jad krwiopijców. Do tego będę musiał podwoić swój zapas.', 0),
(9833, 'plPL', 'Czy robisz postępy w zabezpieczaniu dróg?', 0),
(9834, 'plPL', 'Czy $N ma skóry dla Maktu?', 0),
(9835, 'plPL', 'Jak idzie walka z Ango\'rosh?', 0),
(9839, 'plPL', 'Zrobione? $GRozprawiłeś:Rozprawiłaś; się z Nadrządcą Krwiopięść?', 0),
(9841, 'plPL', 'Dźwięk jakby oddalił się gdzieś w dal. Czy to tylko moje pobożne życzenia, czy naprawdę coś z tym $gzrobiłeś:zrobiłaś;?', 0),
(9842, 'plPL', 'Udało ci się zdobyć trochę tych ostrzy bagiennokłów?', 0),
(9845, 'plPL', 'Mogę już bezpiecznie łowić?', 0),
(9846, 'plPL', '$GZebrałeś:Zebrałaś; te totemy?', 0),
(9847, 'plPL', 'Udało ci się przyzwać ducha z Dzikich Mokradeł?', 0),
(9848, 'plPL', 'Czy przeszukanie Wioski Sztyletowych Mokradeł dało informacje, których potrzebuję, żeby rozwikłać zagadkę tej trucizny?', 0),
(9894, 'plPL', '$GOdnalazłeś:Odnalazłaś; Lorda Klaqa i $gzałatwiłeś:załatwiłaś; sprawę?', 0),
(9895, 'plPL', '$GNatknąłeś:Natknęłaś; się na Bagnobicza?', 0),
(9896, 'plPL', 'Udało ci się zdobyć żądło? Pamiętaj, że jak będzie uszkodzone, na nic mi się nie przyda.', 0),
(9898, 'plPL', 'Moje szczęście zaraz się odmieni – czuję to.', 0),
(9899, 'plPL', 'Przysięgam, nie da się go przekonać. Chyba będę musiała poprosić łowcę cieni Denjaia o przeniesienie z powrotem do Zabra\'jin.', 0),
(9901, 'plPL', 'Udało ci się wytropić Zarodnikoskrzydłego?', 0),
(9902, 'plPL', 'Wstyd mi, że nie mogę zrobić więcej, by pomóc moim zniewolonym braciom, ale przynajmniej zapobiegliśmy kolejnym niepotrzebnym śmierciom.', 0),
(9903, 'plPL', '$GWysłałeś:Wysłałaś; starego Mragesha na „emeryturę”?', 0),
(9904, 'plPL', 'Rozumiem, że Grozoszpon już nie żyje?', 0),
(9905, 'plPL', 'Dawno temu Maktu mógłby zrobić ze skóry Mragesha mocną zbroję. Teraz Mragesh o wiele za stary. Skóra za miękka na dobrą zbroję.', 0),
(9911, 'plPL', '<Wartowniczka kilka razy mruga ze zdumienia.>$B$BSkąd to... coś masz?', 0),
(10012, 'plPL', 'Co tam masz, $N?', 0),
(10013, 'plPL', 'Co tam masz, $N?', 0),
(10096, 'plPL', 'Co? Już z powrotem? Jak poszło?', 0),
(10115, 'plPL', '$GWidziałeś:Widziałaś;, co zrobiło plemię Sztyletowych Mokradeł? Teraz rozumiesz, dlaczego musimy odciąć je od pozostałych Zagubionych.', 0),
(10116, 'plPL', 'A więc chcesz odebrać nagrodę za Wodza Mummakiego?', 0),
(10117, 'plPL', 'A więc chcesz odebrać nagrodę za Wodza Mummakiego?', 0),
(10118, 'plPL', 'Plemię Sztyletowych Mokradeł rozumie tylko szybkie i brutalne działanie. Niech wiedzą, że nie pozwolimy im robić, co chcą.', 0),
(10310, 'plPL', 'W czym mogę pomóc?', 0),
(10355, 'plPL', 'Udało ci się zebrać próbki?', 0),
(10897, 'plPL', 'Na pewno tego chcesz, $N? Specjalizacja w miksturach nie pozwoli ci obrać innych specjalizacji.', 0),
(10961, 'plPL', '$GPrzyniosłeś:Przyniosłaś; składniki na napar? Tylko proszę, uważaj, żeby nie obsypać mnie pyłkiem. Przy nim kicham bez opamiętania.$B$B<Morthis pociąga nosem, urażony na samą myśl o upokarzającym kichnięciu.>', 0),
(10993, 'plPL', 'Czekam na wieści od Arthorn. Czego się $gdowiedziałeś:dowiedziałaś;?', 0),
(10994, 'plPL', 'Wyglądasz, jakby $gprzeszedł:przeszła; ciężką przeprawę. Czy naprawdę tak trudno było znaleźć ten kamień księżycowy?', 0),
(11001, 'plPL', 'Jakie wieści z Sal Sethekk? $GPokonałeś:Pokonałaś; Anzu?', 0),
(11531, 'plPL', 'O rety! Co tam masz, $N?', 0);
