INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(3002, 'plPL', 'Od twojego wyjazdu z Wiecznego Gaju kontynuowałam badania nad Księgą Kruka i odkryłam informacje, które pomogą ci pokonać Boga Kruków.\n\nUwolnienie duchów związało je z tobą, spodziewam się więc, że chętnie udzielą ci pomocy w walce z Bogiem Kruków.\n\nGdy po raz pierwszy uwolnisz duchy, będą uśpione, tak jak były od stuleci. Za pomocą czarów leczących z czasem możesz napełnić je energią, przywrócić do życia i zyskać ich pomoc w walce. Gdy magia przeminie, znów zapadną w sen.\n\nPoniżej zebrałam moje notatki o każdym z ptasich duchów:', 0),
(3003, 'plPL', 'Duch sokoła\n\nDuch sokoła jest obdarzony niezwykłą szybkością i zwinnością, a arakkoa wysoko go cenią za wyborne umiejętności łowieckie. Jeśli pobudzisz go czarem leczącym z czasem, użyczy ci cząstki swojej szybkości w rzucaniu czarów i walce wręcz.\n', 0),
(3004, 'plPL', 'Duch orła\n\nTradycja arakkoa głosi, że duch orła nie był tak szybki jak jego brat sokół, ale za to nie miał sobie równych w łowach. Duch orła użyje swych umiejętności przeciw twoim wrogom, jeśli zbudzisz go ze snu czarem leczącym z czasem.\n\n.', 0),
(3005, 'plPL', 'Duch jastrzębia\n\nTabliczka wyraża się o jastrzębiu z wielkim uznaniem, jak gdyby był on niegdyś w zmowie z krukiem. Ducha jastrzębia, pradawny symbol zemsty u arakkoa, często przyzywały ofiary niegodziwości. Zbudzenie go czarem leczącym z czasem pozwoli ci czerpać z jego mocy i ranić tych, którzy wyrządzają ci krzywdę.\n', 0);
