INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(8778, 'plPL', 'Świąteczne okazje dla ciebie i twoich bliskich!', 'Świąteczne okazje dla ciebie i twoich bliskich!', 0),
(8779, 'plPL', 'Prosto z naszej farmy na twój talerz – zdrowe smakołyki od Wędzonych Pastwisk!', 'Prosto z naszej farmy na twój talerz – zdrowe smakołyki od Wędzonych Pastwisk!', 0),
(8780, 'plPL', 'Nastał czas wielkich okazji! Fa la la la la!', 'Nastał czas wielkich okazji! Fa la la la la!', 0),
(8781, 'plPL', 'Cudownej Zimowej Uczty! Zacznij ją jak należy, od smakołyków z Wędzonych Pastwisk!', 'Cudownej Zimowej Uczty! Zacznij ją jak należy, od smakołyków z Wędzonych Pastwisk!', 0),
(8782, 'plPL', 'Nie zapomnij powiedzieć Praojcu Mrozowi, jaką sekretną niespodziankę chcesz dostać na tę Zimową Ucztę!', 'Nie zapomnij powiedzieć Praojcu Mrozowi, jaką sekretną niespodziankę chcesz dostać na tę Zimową Ucztę!', 0),
(8783, 'plPL', 'Niech dźwięk dzwonków nie zagłuszy brzęku monet w twojej sakiewce! Kup smakołyki od Wędzonych Pastwisk na obchody Zimowej Uczty!', 'Niech dźwięk dzwonków nie zagłuszy brzęku monet w twojej sakiewce! Kup smakołyki od Wędzonych Pastwisk na obchody Zimowej Uczty!', 0),
(8784, 'plPL', 'Ach, kasztany! Gdyby tylko były, zaraz piekłyby się nad otwartym ogniem. Mmmm!', 'Ach, kasztany! Gdyby tylko były, zaraz piekłyby się nad otwartym ogniem. Mmmm!', 0),
(8785, 'plPL', 'Nie zapomnij zaopatrzyć się w papier do pakowania w ten świąteczny czas! Nic tak nie mówi „Cudownej Zimowej Uczty” jak zapakowane zbroje i broń dla przyjaciół i rodziny.', 'Nie zapomnij zaopatrzyć się w papier do pakowania w ten świąteczny czas! Nic tak nie mówi „Cudownej Zimowej Uczty” jak zapakowane zbroje i broń dla przyjaciół i rodziny.', 0),
(14437, 'plPL', '', 'Och, nie zwracaj uwagi na Kumpla. Nic ci nie zrobi, po prostu lubi czasem podrapać.$B$BTo tylko duży, kochany kotek.$B$BPrawda, Kumplu? Tak, prawda, ty słodki maluchu. Jesteś maleństwem mamusi, o tak!', 0),
(14442, 'plPL', 'My, druidzi cenariońscy, jesteśmy obrońcami równowagi natury. A najważniejsza jest tu właśnie równowaga. Kiedy trzeba, nie powinniśmy zbyt długo zwlekać z podjęciem zdecydowanych działań. Nie daj sobie wmówić, że jest inaczej, zwłaszcza tym z nas, którzy chcą tylko obserwować!', '', 0),
(14542, 'plPL', 'Gdyby nasi wrogowie zrozumieli, że chcemy tylko żyć z nimi w zgodzie, może nie musielibyśmy ich atakować, żeby przetrwać?', '', 0),
(14544, 'plPL', 'Skoro u naszych drzwi stoją nowi wrogowie, nie możemy pozwolić, by nasi odwieczni wrogowie wykorzystali nasze położenie!', '', 0),
(14545, 'plPL', '', 'Niesamowite miejsce, co? Choć jak dla mnie trochę tu duszno.', 0),
(14547, 'plPL', 'Plugawe grzybowe olbrzymy! Co my im takiego zrobiliśmy?', '', 0),
(14548, 'plPL', '', 'Gdybym nie skręciła kostki, wchodząc tutaj, byłabym tam razem z przyjaciółmi. Hmm, jak się teraz nad tym zastanowić, to może i lepiej, że siedzę tutaj?', 0),
(14549, 'plPL', 'Fhwoor lubić małe zarodniaki. Oni ratować Fhwoor. Nie jeść ich.$B$BFhwoor nienawidzić nagi. Fhwoor miażdżyć!', '', 0),
(14565, 'plPL', 'Wiatr mówi o ruchach naszych wrogów, Ashyen. Nagi znów zaatakują.', '', 0),
(14567, 'plPL', 'Dobrze. Gdy ta decyzja zapadnie, będę w gotowości. Miejmy nadzieję, że nie będzie za późno.', '', 0),
(14570, 'plPL', 'Oto szczątki Plewiarza Zielonorękiego, jednego z druidzkich towarzyszy Wartowniczki Jhang. Wszystko wskazuje na to, że zginął szybko i czysto, próbując uciec z Zagród Niewolników.', '', 0),
(14571, 'plPL', 'Prawie mi się udało!$B$BPrzyszedłem tu, żeby udowodnić istnienie Quagmirrana, najbardziej mitycznego z grzybowych olbrzymów. Moje życzenie się spełniło, w pewnym sensie.$B$BMusisz mnie uwolnić! W zamian obdarzę cię łaską, która pomoże ci rozprawić się z Quagmirranem.', '', 0),
(14574, 'plPL', 'Dobrze, Ugryzienie, wypuszczę cię.', 'Dobrze, Ugryzienie, wypuszczę cię.', 0),
(14575, 'plPL', 'Ojej! Wygląda na to, że cały ten hałas, który robisz, ściągnął niepożądaną uwagę!', '', 0),
(14584, 'plPL', 'MAM JUŻ... DOSYĆ... CIEBIE!', '', 0),
(14591, 'plPL', 'Dzięki niebiosom, że się $gzjawiłeś:zjawiłaś;! Pazur i ja badaliśmy to miejsce, kiedy napadł na nas Władca Bagien Musel\'ek.$B$BNiestety Pazur był wtedy w niedźwiedziej postaci i teraz jest pupilem władcy bagien.$B$BObawiam się, że będziesz $gmusiał:musiała; walczyć z Pazurem, żeby go uratować.', '', 0),
(14603, 'plPL', 'Wartowniczko Leesa\'oh, co tu robisz?', 'Wartowniczko Leesa\'oh, co tu robisz?', 0),
(14605, 'plPL', '', 'Wszystko w naturze tworzy sieć wzajemnych powiązań, czyli ekologię. Jeśli będziemy uważać, żeby jej nie zaburzyć, i będziemy po prostu obserwować, może uda nam się poskładać w całość złożone relacje między różnorodnymi organizmami wokół nas.$B$BKiedy już je zrozumiemy, możemy podjąć odpowiednie działania, by zapewnić dobrostan wszystkim stworzeniom. Ingerując bez tej wiedzy, z pewnością spowodujemy zniszczenie.$B$BJestem tu, żeby obserwować złożone zależności między zarodniakami a władcami trzęsawisk.', 0),
(14608, 'plPL', '', '$n, chodźmy zobaczyć, czy ten plan zadziała. Chodź, Kumplu!', 0),
(14609, 'plPL', '', 'No dobrze, zobaczmy, jak użyć tych grzybów, które $gprzyniosłeś:przyniosłaś;, żeby wyhodować władcom trzęsawisk nowe źródło pożywienia.', 0),
(14610, 'plPL', '', 'Och, Kumplu, ty duży dzieciaku! Patrz, działa. Naprawdę działa!! Teraz wystarczy, że wyhoduję tu więcej tych grzybów, a władcy trzęsawisk pewnie zostawią zarodniaki w spokoju!', 0),
(14611, 'plPL', '', 'Och, dziękuję, $n! Dzięki tobie da się ocalić i zarodniaki przed władcami trzęsawisk, i władców trzęsawisk przed naszym gniewem.', 0),
(14615, 'plPL', '', 'Zaczekaj i zobacz, co się stanie!', 0),
(14619, 'plPL', 'Druidzi chronią mnie przed nagami i złymi Zagubionymi. W zamian uczę ich o roślinach i zwierzętach moczarów.', '', 0),
(14639, 'plPL', 'Fhwoor iść teraz, $n. Wziąć arka, wrócić.', '', 0),
(14640, 'plPL', 'Chwila... szykować się.', '', 0),
(14641, 'plPL', 'Idziemy!', '', 0),
(14642, 'plPL', '%s bez trudu podnosi Arkę Ssslitha.', '', 0),
(14643, 'plPL', 'Oj, oj...', '', 0),
(14644, 'plPL', 'Ha ha, miękka naga!', '', 0),
(14645, 'plPL', '%s stawia Arkę Ssslitha na ziemi.', '', 0),
(14646, 'plPL', 'Fhwoor dobrze zrobić!', '', 0),
(14668, 'plPL', 'Hej! Tutaj! Tak, tutaj... Jestem w tej klatce!!!', '', 0),
(14669, 'plPL', 'Skoro to niegrzeczne wtargnięcie mamy już za sobą, jak mówiłem, Quagmirran jest niedaleko!$B$BTak jak obiecałem, mogę cię wzmocnić magiczną łaską, która powinna ci pomóc w walce z nim.', '', 0),
(14670, 'plPL', 'Przyrodniku, proszę, obdarz mnie swoją łaską.', 'Przyrodniku, proszę, obdarz mnie swoją łaską.', 0),
(14696, 'plPL', 'Ysiel spodziewała się, że jej wyprawa do Rubieży napotka pewien opór wroga. Dlatego zabrano nas, strażników.$B$BNigdy nie przypuszczaliśmy, że opór będzie tak silny i liczny, jak ten, który stawiły nagi.', '', 0),
(14724, 'plPL', '', 'Droga wolna? Uciekajmy, póki możemy, $n.', 0),
(14725, 'plPL', '', 'Wygląda na to, że nie pójdzie nam tak łatwo. Przygotuj się!', 0),
(14726, 'plPL', '', 'Idźmy dalej. Tu nie jesteśmy bezpieczni!', 0),
(14727, 'plPL', '', 'Uważaj, $n! Wrogowie przed nami!', 0),
(14728, 'plPL', '', 'Jesteśmy już prawie przy schronieniu! Chodźmy.', 0),
(14729, 'plPL', '', 'Widzę już stąd moich towarzyszy druidów. Dziękuję ci, $n. Na pewno Ysiel wynagrodzi cię za to, co $gzrobiłeś:zrobiłaś;!', 0),
(14738, 'plPL', 'Natura sprzyja tym, którzy chcą poznać jej tajemnice, $n.', '', 0),
(14739, 'plPL', 'Obdarz mnie swoim znakiem, mądre pradrzewo.', 'Obdarz mnie swoim znakiem, mądre pradrzewo.', 0),
(14740, 'plPL', 'Natura to potężna siła. Tym, którzy próbują ją ujarzmić, nigdy nie udaje się to na zawsze.', '', 0),
(14741, 'plPL', 'Obdarz mnie swoim znakiem, potężne pradrzewo.', 'Obdarz mnie swoim znakiem, potężne pradrzewo.', 0),
(14777, 'plPL', '', 'Niech wiatry cię prowadzą, $n.', 0),
(14779, 'plPL', 'Ta księga zawiera informacje o gatunkach roślin Rubieży. Większość opisanych roślin pochodzi z Moczarów Zangarskich.$B$BWykresy i szkice są trochę ponad twoje zrozumienie. Może autorka mogłaby ci coś podpowiedzieć.', '', 0),
(14786, 'plPL', 'Jeszcze nie wiem, co myśleć o twoich pobratymcach. Niektórzy z was bywają agresywni i zabijają zarodniaki od razu, gdy je zobaczą.$B$BTy wydajesz się $gprzyjazny:przyjazna;... choć chyba trochę śmiesznie wyglądasz.', '', 0),
(14788, 'plPL', 'Witaj w Sporeggarze. Zwykle nie widujemy tu wielu twoich pobratymców, ale $gudowodniłeś:udowodniłaś; nam, ile jesteś $gwart:warta;. Czuj się jak u siebie.', '', 0),
(14789, 'plPL', 'Władcy trzęsawisk pożerają worki zarodników! Trzeba ich powstrzymać!', '', 0),
(14853, 'plPL', '%s głośno syczy i szykuje się do ataku.', '', 0),
(14871, 'plPL', 'Pokornie witam cię w naszej świątyni, duchu.', '', 0),
(14872, 'plPL', 'Witaj, starszy. Czas, by twój lud zakończył wrogość wobec draenei i ich sojuszników.', 'Witaj, starszy. Czas, by twój lud zakończył wrogość wobec draenei i ich sojuszników.', 0),
(14873, 'plPL', 'Paktować z draenei, z ludem, który odwrócił się od nas, gdy cierpieliśmy? Nie sądzę.$B$BPrawdziwy duch tak nie mówi! Ujawnij się, oszuście. Kto cię przysłał?', '', 0),
(14874, 'plPL', 'Nie było moim zamiarem cię oszukać, starszy. Draenei z Telredoru uznali, że zbliżą się do was w sposób, który będzie wam znajomy.', 'Nie było moim zamiarem cię oszukać, starszy. Draenei z Telredoru uznali, że zbliżą się do was w sposób, który będzie wam znajomy.', 0),
(14876, 'plPL', 'Mamy więc ufać ludziom, którzy obrażają nas takim oszustwem? Czy draenei mają nas za tak nic niewartych, że muszą uciekać się do podstępów, by zwrócić naszą uwagę?$B$BWiemy, że chcą nas „odkupić”, ale mój lud nie chce żadnego ich odkupienia. Potrafimy radzić sobie sami i będziemy dążyć do swojego przeznaczenia jako dumny i odrębny lud. Zanieś tę wiadomość swoim sojusznikom.', '', 0),
(14879, 'plPL', 'Powiem im. Żegnaj, starszy.', 'Powiem im. Żegnaj, starszy.', 0),
(14880, 'plPL', 'Dobrze. Dopilnuj, żeby zrozumieli.$B$BA teraz byłbym wdzięczny, gdybyś $gzostawił:zostawiła; moją świątynię w spokoju.', '', 0),
(14920, 'plPL', 'Witaj w Przystani Orebor, przyjacielu. Nie masz się tu czego obawiać. Jesteśmy Złamanymi, ale nie jesteśmy twoimi wrogami.$B$BJestem Ikuti z Kurenai, grupy Złamanych, którzy pragną odnowić więzi z naszymi draenejskimi braćmi i ich nowymi sojusznikami.', '', 0),
(14921, 'plPL', 'Maktu cię nie zna, ale cieszy się, że cię poznał. Jeśli kiedyś będziesz $gchciał:chciała; kupić albo naprawić zbroję, nie szukaj dalej niż u Maktu.', '', 0),
(14923, 'plPL', 'Pokaż mi swoje towary, Maktu.', 'Pokaż mi swoje towary, Maktu.', 0),
(14924, 'plPL', 'Wspomnienia o tej świątyni spowijają mój umysł jak gęsta mgła, ale nie potrafię ułożyć ich w spójną opowieść. To miejsce kiedyś coś dla mnie znaczyło. Dopóki nie odzyskam tego wspomnienia, będę się czuł, jakby brakowało mi cząstki samego siebie.$B$BMoże draenei pomogą mi odzyskać to, co utraciłem.', '', 0),
(14930, 'plPL', 'Pokaż mi swoje składniki i zapasy trucizn.', 'Pokaż mi swoje składniki i zapasy trucizn.', 0),
(14931, 'plPL', 'Niektórzy mówią na mnie „Tim”, ale dla przyjaciół jestem „specjalistą”.', '', 0),
(14932, 'plPL', 'Specjalista, co? A w czym właściwie się specjalizujesz?', 'Specjalista, co? A w czym właściwie się specjalizujesz?', 0),
(14933, 'plPL', 'Jeśli musisz pytać, to znasz mnie o wiele za słabo, żeby używać tego miana.', '', 0),
(14945, 'plPL', 'Witaj w Zabra\'jin. Jestem łowca cieni Denjai, nadzorca tej placówki i dowódca sił Mrocznej Włóczni na Moczarach Zangarskich.', '', 0),
(14946, 'plPL', 'Nawet nie myśl o tym, żeby zwiać z moimi małymi murlokami! Mam oczy jak jastrząb i uszy jak... uszy jak... jak coś, co ma bardzo potężne uszy!', '', 0),
(14947, 'plPL', '', 'Tor\'gash wierzy, że widzi przyszłość we wnętrznościach ptaków albo w rzucanych kostkach swoich przodków. A tak naprawdę wystarczy zapytać duchy. Ale nie próbuj mu tego mówić, $n. Jest bardzo uparty.', 0),
(14957, 'plPL', 'Kiedy pierwszy raz zobaczyłem grzyby wyższe od drzew, nie byłem pewien, czy zdołam nazwać to miejsce domem. Po jakimś czasie po prostu przestaje się to zauważać.', '', 0),
(14958, 'plPL', 'Chcę kupić materiały rzemieślnicze.', 'Chcę kupić materiały rzemieślnicze.', 0),
(14959, 'plPL', '', 'Kiedy już jesteś na Moczarach Zangarskich, nie zapomnij znaleźć czasu na wędkowanie. Nigdy nie wiadomo, kiedy znów zobaczysz wodę.', 0),
(14960, 'plPL', 'Chcę kupić sprzęt wędkarski.', 'Chcę kupić sprzęt wędkarski.', 0),
(14961, 'plPL', 'Daj mi kilka wskazówek co do mojej techniki wędkowania.', 'Daj mi kilka wskazówek co do mojej techniki wędkowania.', 0),
(14962, 'plPL', 'Telredor był kiedyś ustronnym schronieniem dla draenejskich kapłanów i pielgrzymów. Mieszkający tu kapłani rzadko przyjmowali gości.$B$BGdy orkowie zaczęli atakować draenejskie osady, zaczęli tu napływać liczniej uchodźcy. Anachoreta Ahuurn i inni przemienili Telredor z sanktuarium w bezpieczną przystań. Wielu draenei, łącznie ze mną, zawdzięcza przetrwanie jego staraniom.', '', 0),
(14966, 'plPL', '', 'Widok ze szczytu Telredoru jest wspaniały, prawda?', 0),
(14968, 'plPL', 'Witaj w Telredorze. Jeśli czegoś potrzebujesz, nie wahaj się pytać.', '', 0),
(14972, 'plPL', 'Nigdy nie widziałem tylu rodzajów grzybów w jednym miejscu. Gdybym miał dość czasu, na pewno znalazłbym zastosowanie dla każdego z nich.', '', 0),
(14973, 'plPL', 'Telredor przez ostatnie 20 lat przeszedł więcej zmian niż przez wcześniejsze stulecia. Nie mogę narzekać, $n, bo w tym czasie świat zmienił się znacznie bardziej.$B$BŚwiatłość dała mi przyjaciół i towarzyszy, których nie mógłbym poznać jako kapłan zamknięty w klasztorze. Dowiedz się jak najwięcej o przeszłości, póki tu jesteś. Pomoże ci to zrozumieć, dokąd prowadzi cię twoja podróż.', '', 0),
(14980, 'plPL', 'Jeśli kiedyś spotkasz znachora Tor\'gasha, powiedz mu, że jego mikstury i amulety nie działają! Zrobiłem dokładnie tak, jak mi kazał, a Magasha i tak ma oczy tylko dla Zuraia.$B$BNie wierz w ani jedno słowo tego szarlatana!', '', 0),
(14981, 'plPL', '', 'Reavij jest subtelny jak kodo! A najśmieszniejsze, że on myśli, że nic po nim nie widać. Widzę, jak się na mnie gapi, kiedy myśli, że nikt nie patrzy.$B$BAż mnie ciarki przechodzą. Naprawdę wolałabym, żeby łowca cieni Denjai go z nami nie wysyłał. Zakładanie Posterunku Bagiennego Szczura było idealną okazją, żeby się od niego uwolnić.', 0),
(14994, 'plPL', 'Tu wywieszono obwieszczenia o nagrodach za przywódców nag z plemion Mrocznego Grzebienia i Krwawej Łuski.', '', 0),
(15199, 'plPL', 'Zapłacisz mi za to!', '', 0),
(15201, 'plPL', 'Wódz Kalithresh usłyszy o tym zuchwalstwie!', '', 0),
(15202, 'plPL', 'Nauczę cię, że z nami się nie zadziera!', '', 0),
(15331, 'plPL', 'Żaden przerośnięty robal nie przegoni mnie z Moczarów Zangarskich! Pokażę im, z czego jest ulepiona Liga Odkrywców...', '', 0),
(15561, 'plPL', 'Fszszszszszsssfszsz?', '', 0),
(15565, 'plPL', 'F\'wuuuroonn! Coosh\'coosh nic nie płacić! Giń!', '', 0),
(15685, 'plPL', 'Witaj w Forcie Alleriańskim.', '', 0),
(16012, 'plPL', 'Usiądź, $gbracie:siostro;. Trudy Moczarów Zangarskich potrafią porządnie wymęczyć.', '', 0),
(16013, 'plPL', 'Jak chcesz tu odpocząć, wystarczy poprosić!', '', 0),
(16291, 'plPL', 'Tę starą draenejską tablicę odnowili Kurenai i teraz wywiesza się na niej ogłoszenia i nagrody.', '', 0),
(16293, 'plPL', 'Łowca cieni Denjai wywiesza na tej tablicy ważne ogłoszenia i wieści o nagrodach za wrogów Zabra\'jin.', '', 0),
(16532, 'plPL', '', 'Pospiesz się z tym toporem! Ma być tak ostry, żeby ciął wiatr!', 0),
(16538, 'plPL', '', 'Jak się nie nadajesz do naprawiania, sprawdzimy, czy nadajesz się do jedzenia. A teraz do ROBOTY!', 0),
(16540, 'plPL', 'Nie rozumiem cię!', '', 0),
(16541, 'plPL', 'Proszę, nie bij mnie!', '', 0),
(17073, 'plPL', '', 'Nigdy bym nie pomyślała, że to okaże się olej many! Popyt będzie ogromny, nie licząc oczywiście Greka!', 0),
(17075, 'plPL', '', 'Wysyłać!', 0),
(17724, 'plPL', 'Uważacie się za godnych tylko dlatego, że pokonaliście moich strażników? Nie pozwolę, by nasza praca tutaj została zagrożona!', '', 0),
(17725, 'plPL', 'To jeszcze nie koniec...', '', 0),
(17726, 'plPL', 'Twoja głowa się potoczy!', '', 0),
(17727, 'plPL', 'Gardzę całym twoim rodem!', '', 0),
(17728, 'plPL', 'Ba\'anthalso-dorei!', '', 0),
(17729, 'plPL', 'Wij się, plugawcze z powierzchni!', '', 0),
(17730, 'plPL', 'Dla Jej Ekscelencji... dla... Vash!', '', 0),
(18325, 'plPL', '%s przestaje udawać martwego i rusza do szarży!', '', 0),
(18719, 'plPL', '%s przegląda informacje na liście gończym.', '', 0),
(18720, 'plPL', 'Jeśli jeszcze tego nie $gzrobiłeś:zrobiłaś;, koniecznie zaoferuj swoją pomoc Rinie Moonspring.', '', 0),
(18721, 'plPL', 'Jeśli dobrze słyszałem, już dobrze się sprawujesz dla Sylvanaar.$B$BTak trzymaj, a może uda nam się zatrzymać tu nasz dom.', '', 0),
(18746, 'plPL', 'Nie tak dawno temu musieliśmy wyrwać Warownię Władców Gromu z rąk okolicznych ogrów.$B$BPrzybywasz, żeby pomóc nam utrzymać obronę? Wiem, że Gor\'drek szuka pomocy.', '', 0),
(18781, 'plPL', '%s zaczyna czytać list gończy.', '', 0),
(18782, 'plPL', 'Pochrząkując, %s odwraca się od listu gończego i wraca na swoje ciepłe miejsce przy ogniu.', '', 0),
(18791, 'plPL', '', 'Witaj w Schronieniu Cenariona, $n. Polecono mi oferować ci podstawowe zapasy na sprzedaż, jeśli będziesz ich potrzebować.', 0),
(18913, 'plPL', '%s rzuca w $n grzybowym zarodnikiem.', '', 0),
(19166, 'plPL', '%s zaczyna czerpać moc z pobliskiego destylatora...', '', 0),
(20454, 'plPL', 'Jest mi smutno i samotnie. Szkoda, że nie ma tu więcej dzieci w moim wieku. Czasem tęsknię za sierocińcem w Shattrath.', '', 0),
(20636, 'plPL', '', 'Witaj w Wiecznym Gaju. Timeon i ja od jakiegoś czasu badamy arakkoa z Gór Klingi i odkryliśmy niepokojące różnice między nimi a ich kuzynami z Terokkaru.', 0),
(20752, 'plPL', '', 'Bez ciebie szukanie Księgi Kruka trwałoby latami, mały krogulcze. Wracaj do domu w Nagrandzie z naszą wdzięcznością.', 0),
(20753, 'plPL', '', 'To jest to! To naprawdę ona – Księga Kruka!', 0),
(20756, 'plPL', '', 'Wszystko tu jest... jak wyznawcy kruka chwytali i ujarzmiali duchy rywali, więżąc je na zawsze w kamiennych posągach! Tablica wymienia nawet imię kruczego boga – Anzu. Myślałam, że przepadło w mrokach dziejów!', 0),
(20757, 'plPL', '', 'Jest tu też coś jeszcze. Po opisie krwawej bitwy i upadku kruka jest przepowiednia. Anzu będzie nawiedzał sny swoich wrogów, wypaczając je, by powrócić na ten świat...', 0),
(20758, 'plPL', '', 'Tablica zawiera potwierdzenie, którego potrzebujemy, tak jak myślałam. Teraz musimy wykorzystać te informacje, by wywabić i pokonać tego Anzu, zanim wyrządzi Szmaragdowemu Snowi więcej szkód!', 0),
(20991, 'plPL', 'Przebudźcie się, moje dzieci, i wspomóżcie swojego pana!', '', 0),
(21012, 'plPL', 'Tak... rzucajcie swoje cenne zaklęcionka, ak-a-ak!', '', 0),
(21017, 'plPL', 'Wasze zaklęcia... ke-kau... to słaba magia... łatwo obrócić ją przeciwko wam...', '', 0),
(21433, 'plPL', 'Ekspedycja Cenariońska uratowała mnie przed pewną śmiercią w kopalniach. Zawdzięczam jej życie! Sojusznikom Ekspedycji Cenariońskiej oferuję naprawy i sprzedaż składników.', '', 0),
(21607, 'plPL', '', 'Skoro krogulce tak świetnie się sprawdziły w tropieniu kruczych kamieni, Wartowniczka Elaira wyszkoliła kolejnego, który będzie przekazywał mój głos na wielką odległość. Pomoże nam się porozumiewać, gdy będziesz badać ptasie duchy, o których mówi tablica!', 0),
(34245, 'plPL', 'Chcę się szkolić w wędkarstwie.', 'Chcę się szkolić w wędkarstwie.', 0);
